import { defineStore } from 'pinia'
import { API } from '@/configurations'
import { fetchRates } from '@/services/nbu'

let retryTimer = null

export const useRatesStore = defineStore('rates', {
  state: () => ({
    rates: {},
    date: '',
    loading: false,
    // Курса ещё нет, а последняя попытка загрузки не удалась
    failed: false,
  }),

  getters: {
    loaded: (state) => Object.keys(state.rates).length > 0,
  },

  actions: {
    // Пока курса нет, запрос повторяется каждые API.RETRY_MS, а интерфейс показывает индикатор загрузки
    async load() {
      if (this.loading) return
      clearTimeout(retryTimer)
      this.loading = true
      try {
        const { date, rates } = await fetchRates()
        this.date = date
        this.rates = rates
        this.failed = false
      } catch {
        if (!this.loaded) {
          this.failed = true
          retryTimer = setTimeout(() => this.load(), API.RETRY_MS)
        }
      } finally {
        this.loading = false
      }
    },

    cancelRetry() {
      clearTimeout(retryTimer)
    },
  },
})
