import { defineStore } from 'pinia'
import { API, STORAGE_KEYS, WEATHER } from '@/configurations'
import { fetchWeather } from '@/services/weather'
import { readStorage, writeStorage } from '@/utils/storage'

const cityIds = WEATHER.CITIES.map((city) => city.id)

// Ответы приходят в произвольном порядке: побеждает только последний запрос
let requestId = 0
let retryTimer = null

export const useWeatherStore = defineStore('weather', {
  state: () => {
    const saved = readStorage(STORAGE_KEYS.WEATHER_CITY)
    return {
      city: cityIds.includes(saved) ? saved : WEATHER.DEFAULT_CITY,
      data: null,
      loading: false,
      // Погоды ещё нет, а последняя попытка загрузки не удалась
      failed: false,
    }
  },

  actions: {
    cancelRetry() {
      clearTimeout(retryTimer)
    },

    setCity(id, lang) {
      if (!cityIds.includes(id) || id === this.city) return
      this.city = id
      writeStorage(STORAGE_KEYS.WEATHER_CITY, id)
      // Погода прежнего города не должна выглядеть как погода нового
      this.data = null
      this.failed = false
      return this.load(lang)
    },

    // Пока погоды нет, запрос повторяется каждые API.RETRY_MS, а интерфейс показывает индикатор загрузки
    async load(lang) {
      clearTimeout(retryTimer)
      const id = ++requestId
      const { query } = WEATHER.CITIES.find((city) => city.id === this.city)
      this.loading = true
      try {
        const data = await fetchWeather(query, lang)
        if (id !== requestId) return
        this.data = data
        this.failed = false
      } catch {
        if (id !== requestId) return
        if (!this.data) {
          this.failed = true
          retryTimer = setTimeout(() => this.load(lang), API.RETRY_MS)
        }
      } finally {
        if (id === requestId) this.loading = false
      }
    },
  },
})
