import { defineStore } from 'pinia'
import { MANAGERS } from '@/configurations'
import { useAccessStore } from '@/stores/access'
import { useCompanyStore } from '@/stores/company'
import { useManagersStore } from '@/stores/managers'

// «Область» страницы: о чём сейчас показаны все блоки. Главная — это компания, а сравниваются менеджеры;
// страница РМ — это сам менеджер, а сравниваются его магазины. Блоки страницы (карточки, графики, матрицы)
// читают данные отсюда и не знают, на какой странице стоят: поэтому на странице РМ работают те же самые компоненты.
// Выбранный период тоже хранится здесь и общий для всех страниц.
export const useScopeStore = defineStore('scope', {
  state: () => ({
    // id менеджера, чья страница открыта; null — главная страница компании
    managerId: null,
    // time выбранного периода; null — последний период
    selectedTime: null,
  }),

  getters: {
    manager: (state) => MANAGERS.find((item) => item.id === state.managerId) || null,

    // managers — сравнение менеджеров (главная), stores — сравнение магазинов одного менеджера
    kind() {
      return this.manager ? 'stores' : 'managers'
    },

    // Блок «Интернет-магазин / Мономаркет» есть только у компании
    hasChannels() {
      return !this.manager
    },

    // Итоговые строки по всем периодам: у компании — её таблица, у менеджера — первые строки его периодов
    rows() {
      if (!this.manager) return useCompanyStore().rows
      const source = useManagersStore().sources[this.manager.id]
      return source ? source.times.map((time) => source.totals[time]) : []
    },

    loaded() {
      return this.rows.length > 0
    },

    // Самый свежий период
    latest() {
      return this.rows.length ? this.rows[this.rows.length - 1] : null
    },

    // Период, по которому показывается вся страница: выбранный, а если не выбран или его нет в этой таблице — последний
    current(state) {
      return this.rows.find((row) => row.time === state.selectedTime) || this.latest
    },

    period() {
      return this.current ? this.current.time : ''
    },

    // Менеджер загружен, но данных за выбранный период нет
    empty() {
      if (!this.manager) return false
      const source = useManagersStore().sources[this.manager.id]
      return !!source && source.status === 'ready' && !this.current
    },

    // Строки для сравнения на странице: у компании — итоги менеджеров, у менеджера — его магазины.
    // Форма записи одна: { manager: { id, name, color }, status, row }. Магазины рисуются цветом своего менеджера.
    totals() {
      const time = this.period
      if (this.manager) {
        const source = useManagersStore().sources[this.manager.id]
        const stores = source && time ? source.stores[time] || [] : []
        return stores.map((row, index) => ({
          manager: { id: `${index}:${row.company}`, name: row.company, color: this.manager.color },
          status: 'ready',
          row,
        }))
      }

      const sources = useManagersStore().sources
      return useAccessStore().allowedManagers.map((manager) => {
        const source = sources[manager.id]
        return { manager, status: source ? source.status : 'idle', row: (source && time && source.totals[time]) || null }
      })
    },
  },

  actions: {
    // Вызывается страницей при открытии: null — главная, id — страница менеджера
    use(managerId) {
      this.managerId = managerId
    },

    select(time) {
      this.selectedTime = this.rows.some((row) => row.time === time) ? time : null
    },
  },
})
