<template>
  <v-app>
    <v-main>
      <router-view />
    </v-main>
  </v-app>
</template>

<script>
import { mapState } from 'pinia'
import { APP } from '@/configurations'
import { useAccessStore } from '@/stores/access'
import { useSettingsStore } from '@/stores/settings'

export default {
  name: 'App',

  computed: {
    ...mapState(useSettingsStore, ['theme', 'locale']),
    ...mapState(useAccessStore, ['isAuthenticated']),
  },

  watch: {
    // Вход отозван (выход, истёк срок, пользователя удалили, выход в другой вкладке) — уводим с закрытых страниц.
    // Вход в другой вкладке — уводим со страницы входа.
    isAuthenticated(authenticated) {
      if (!authenticated && !this.$route.meta.public) {
        this.$router.replace({ name: 'login' })
      } else if (authenticated && this.$route.name === 'login') {
        this.$router.replace(useAccessStore().homeRoute)
      }
    },

    theme: {
      immediate: true,
      handler(theme) {
        this.$vuetify.theme.change(theme)
      },
    },

    locale: {
      immediate: true,
      handler(locale) {
        this.$i18n.locale = locale
        document.documentElement.lang = locale
      },
    },
  },

  created() {
    document.title = APP.TITLE
    useAccessStore().watchSession()
  },
}
</script>
