const isNumber = (value) => typeof value === 'number' && Number.isFinite(value)

// Выполнение плана в процентах или null, если плана нет
export function completion(fact, plan) {
  return isNumber(fact) && isNumber(plan) && plan !== 0 ? (fact / plan) * 100 : null
}

// Рост к прошлому году в процентах или null, если сравнивать не с чем
export function growth(fact, past) {
  return isNumber(fact) && isNumber(past) && past !== 0 ? (fact / past - 1) * 100 : null
}

// good — план выполнен, warn — почти, bad — отстаёт, none — нет данных
export function statusOf(percent) {
  if (percent === null) return 'none'
  if (percent >= 100) return 'good'
  return percent >= KPI.WARN_FROM ? 'warn' : 'bad'
}

// Если в блоке сравнения больше строк, строки рисуются компактно (страница РМ с 10–14 магазинами), чтобы блок помещался на экране
export const DENSE_FROM = 7
