<template>
  <v-navigation-drawer
    :model-value="desktop || modelValue"
    :permanent="desktop"
    :temporary="!desktop"
    :width="isRail ? 84 : 272"
    :scrim="!desktop"
    class="sidebar"
    :class="{ 'sidebar--rail': isRail, 'sidebar--light': !isDark }"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <div class="sidebar__glow" aria-hidden="true"></div>

    <div class="sidebar__inner">
      <router-link :to="{ name: 'home' }" class="sidebar__brand" :aria-label="appName">
        <img :src="logo" :alt="appName" class="sidebar__logo" width="44" height="44" />
        <span class="sidebar__name">{{ appName }}</span>
      </router-link>

      <nav class="sidebar__nav" :aria-label="$t('common.mainNav')">
        <p class="sidebar__caption">{{ $t('common.menu') }}</p>

        <!-- Региональный менеджер видит одну кнопку: обновить данные своей страницы -->
        <button
          v-if="ownManager"
          type="button"
          class="sidebar__link sidebar__link--button"
          :disabled="refreshing"
          :style="{ '--i': 0 }"
          @click="onRefresh"
        >
          <v-progress-circular v-if="refreshing" indeterminate size="22" width="2.5" class="sidebar__icon" />
          <v-icon v-else :icon="mdiRefresh" size="22" class="sidebar__icon" />
          <span class="sidebar__label">{{ $t('common.refresh') }}</span>
          <v-tooltip v-if="isRail" activator="parent" location="end" :text="$t('common.refresh')" />
        </button>

        <template v-else>
          <router-link
            v-for="(item, index) in items"
            :key="item.route"
            :to="{ name: item.route }"
            class="sidebar__link"
            exact-active-class="sidebar__link--active"
            :style="{ '--i': index }"
            @click="onNavigate"
          >
            <v-icon :icon="item.icon" size="22" class="sidebar__icon" />
            <span class="sidebar__label">{{ $t(item.title) }}</span>
            <v-tooltip v-if="isRail" activator="parent" location="end" :text="$t(item.title)" />
          </router-link>

          <!-- Кнопки менеджеров: столько, сколько РМ доступно пользователю -->
          <template v-if="managers.length">
            <p class="sidebar__caption sidebar__caption--section">{{ $t('nav.managers') }}</p>

            <router-link
              v-for="(manager, index) in managers"
              :key="manager.id"
              :to="{ name: 'manager', params: { id: manager.id } }"
              class="sidebar__link sidebar__link--manager"
              exact-active-class="sidebar__link--active"
              :style="{ '--i': items.length + index, '--mc': manager.color }"
              @click="onNavigate"
            >
              <span class="sidebar__badge" aria-hidden="true">{{ initial(manager.name) }}</span>
              <span class="sidebar__label">{{ manager.name }}</span>
              <v-tooltip v-if="isRail" activator="parent" location="end" :text="manager.name" />
            </router-link>
          </template>
        </template>
      </nav>

      <div class="sidebar__user">
        <span class="sidebar__avatar" aria-hidden="true">
          <span class="sidebar__avatar-face">
            <v-icon :icon="mdiAccount" size="22" />
          </span>
        </span>
        <span class="sidebar__login">{{ currentUser ? currentUser.login : $t('common.guest') }}</span>
        <v-btn
          :aria-label="$t('common.logout')"
          class="sidebar__logout"
          variant="text"
          size="small"
          @click="confirmOpen = true"
        >
          <v-icon :icon="mdiLogout" />
          <v-tooltip activator="parent" location="top" :text="$t('common.logout')" />
        </v-btn>
      </div>
    </div>

    <v-snackbar v-model="notice.open" :color="notice.error ? 'error' : 'success'" timeout="3500" location="bottom" rounded="pill">
      {{ notice.text }}
    </v-snackbar>

    <v-dialog v-model="confirmOpen" max-width="400" transition="scale-transition">
      <v-card class="sidebar__dialog" rounded="xl">
        <v-card-title class="sidebar__dialog-title">{{ $t('common.logoutTitle') }}</v-card-title>
        <v-card-text>{{ $t('common.logoutText') }}</v-card-text>
        <v-card-actions class="sidebar__dialog-actions">
          <v-spacer />
          <v-btn variant="text" rounded="pill" @click="confirmOpen = false">{{ $t('common.cancel') }}</v-btn>
          <v-btn color="error" variant="flat" rounded="pill" @click="onLogout">{{ $t('common.logout') }}</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
  </v-navigation-drawer>
</template>

<script>
import { mapActions, mapState } from 'pinia'
import { mdiAccount, mdiLogout, mdiRefresh, mdiViewDashboardOutline } from '@mdi/js'
import logo from '@/assets/logo.png'
import { APP, PERMISSIONS } from '@/configurations'
import { useAccessStore } from '@/stores/access'
import { useManagersStore } from '@/stores/managers'
import { useSettingsStore } from '@/stores/settings'

export default {
  name: 'AppSidebar',

  props: {
    // Открыт ли выдвижной сайдбар (телефон и планшет)
    modelValue: {
      type: Boolean,
      default: false,
    },
    // Узкий сайдбар только с иконками (компьютер)
    rail: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['update:modelValue'],

  data() {
    return {
      logo,
      mdiAccount,
      mdiLogout,
      mdiRefresh,
      confirmOpen: false,
      // Уведомление после обновления данных
      notice: { open: false, error: false, text: '' },
      appName: APP.NAME,
      // Новые страницы добавляются сюда; permission скрывает пункт от тех, кому он недоступен
      navItems: [{ route: 'home', title: 'nav.home', icon: mdiViewDashboardOutline, permission: PERMISSIONS.DASHBOARD_VIEW }],
    }
  },

  computed: {
    ...mapState(useAccessStore, ['currentUser', 'can', 'ownManager', 'allowedManagers']),
    ...mapState(useSettingsStore, ['isDark']),

    desktop() {
      return this.$vuetify.display.mdAndUp
    },

    isRail() {
      return this.rail && this.desktop
    },

    items() {
      return this.navItems.filter((item) => this.can(item.permission))
    },

    // Страницы РМ, доступные пользователю
    managers() {
      return this.allowedManagers
    },

    // Идёт обновление данных менеджера
    refreshing() {
      const own = this.ownManager
      return own ? !!useManagersStore().sources[own.id]?.refreshing : false
    },
  },

  methods: {
    ...mapActions(useAccessStore, ['logout']),

    onLogout() {
      this.confirmOpen = false
      this.logout()
    },

    // Первая буква имени для круглого значка менеджера
    initial(name) {
      return String(name || '?').trim().charAt(0).toUpperCase()
    },

    // Перечитывает таблицу менеджера; при сбое остаются прежние данные
    async onRefresh() {
      const own = this.ownManager
      if (!own || this.refreshing) return
      const ok = await useManagersStore().refresh(own.id)
      this.notice = { open: true, error: !ok, text: this.$t(ok ? 'common.refreshed' : 'common.refreshFailed') }
      if (!this.desktop) this.$emit('update:modelValue', false)
    },

    onNavigate() {
      if (!this.desktop) this.$emit('update:modelValue', false)
    },
  },
}
</script>

