<template>
  <!-- Одна страница для главной и для страниц РМ: что показывать, решает область данных (stores/scope.js) -->
  <div v-if="empty" :key="managerId || 'home'" class="home home--empty">
    <v-icon :icon="mdiDatabaseOffOutline" size="44" class="home__empty-icon" />
    <p class="home__empty-text">{{ $t('home.noPeriodData') }}</p>
  </div>

  <!-- key: при переходе с одной страницы на другую блоки создаются заново, а не подменяют данные на лету -->
  <div v-else :key="managerId || 'home'" class="home" :class="{ 'home--stores': !!manager }">
    <section class="home__cards" :aria-label="title">
      <kpi-card
        v-for="(metric, index) in metrics"
        :key="metric.id"
        class="home__card"
        :metric="metric"
        :row="current"
        :index="index"
        :loading="!current"
        @trend="openTrend(metric)"
      />
    </section>

    <template v-if="hasChannels">
      <section-divider />

      <section class="home__channels" :aria-label="$t('kpi.shop') + ' / ' + $t('kpi.mono')">
        <channel-card
          v-for="(metric, index) in channels"
          :key="metric.id"
          class="home__channel"
          :metric="metric"
          :row="current"
          :index="metrics.length + index"
          :loading="!current"
          @trend="openTrend(metric)"
        />
      </section>
    </template>

    <!-- Если у РМ один магазин, сравнивать нечего: те же блоки, но компактной сеткой по два в ряд -->
    <template v-if="single">
      <section-divider />

      <div class="home__compact">
        <managers-plan-chart v-for="chart in managerCharts" :key="chart.id" :chart="chart" />
        <check-by-managers />
        <conversion-by-managers />
        <credit-by-managers />
        <items-by-managers />
        <managers-traffic />
        <category-share />
      </div>
    </template>

    <!-- Блоки сравнения: на главной по менеджерам, на странице РМ по его магазинам. Без магазинов сравнивать нечего -->
    <template v-else-if="hasEntries">
      <section-divider />

      <template v-for="chart in managerCharts" :key="chart.id">
        <managers-plan-chart :chart="chart" />
        <!-- Разделитель после каждого графика: перед следующим блоком -->
        <section-divider />
      </template>

      <managers-traffic />

      <section-divider />

      <!-- Средний чек и конверсия стоят рядом; когда места мало, переходят друг под друга -->
      <div class="home__pair">
        <check-by-managers />
        <conversion-by-managers />
      </div>

      <section-divider />

      <!-- Кредит и количество позиций: тоже в одну строку -->
      <div class="home__pair">
        <credit-by-managers />
        <items-by-managers />
      </div>

      <section-divider />

      <category-share />
    </template>

    <section-divider />

    <situation-analytics />

    <kpi-trend-dialog v-model="trendOpen" :metric="trendMetric" :rows="rows" :selected="period" />
  </div>
</template>

<script>
import { mapState } from 'pinia'
import { mdiDatabaseOffOutline } from '@mdi/js'
import CategoryShare from '@/components/CategoryShare.vue'
import ChannelCard from '@/components/ChannelCard.vue'
import CreditByManagers from '@/components/CreditByManagers.vue'
import ItemsByManagers from '@/components/ItemsByManagers.vue'
import CheckByManagers from '@/components/CheckByManagers.vue'
import ConversionByManagers from '@/components/ConversionByManagers.vue'
import KpiCard from '@/components/KpiCard.vue'
import KpiTrendDialog from '@/components/KpiTrendDialog.vue'
import ManagersPlanChart from '@/components/ManagersPlanChart.vue'
import ManagersTraffic from '@/components/ManagersTraffic.vue'
import SectionDivider from '@/components/SectionDivider.vue'
import SituationAnalytics from '@/components/SituationAnalytics.vue'
import { useScopeStore } from '@/stores/scope'
import { CHANNEL_METRICS, KPI_METRICS, MANAGER_CHARTS } from '@/utils/kpi'

export default {
  name: 'HomeView',

  components: { CategoryShare, ChannelCard, CreditByManagers, ItemsByManagers, CheckByManagers, ConversionByManagers, KpiCard, KpiTrendDialog, ManagersPlanChart, ManagersTraffic, SectionDivider, SituationAnalytics },

  data() {
    return {
      mdiDatabaseOffOutline,
      metrics: KPI_METRICS,
      channels: CHANNEL_METRICS,
      managerCharts: MANAGER_CHARTS,
      trendOpen: false,
      trendMetric: null,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['rows', 'current', 'period', 'empty', 'hasChannels', 'manager', 'totals']),

    // Название области для скринридера: имя менеджера или «Головна»
    title() {
      return this.manager ? this.manager.name : this.$t('home.title')
    },

    // Есть ли что сравнивать: менеджеры на главной, магазины на странице РМ
    hasEntries() {
      return this.totals.length > 0
    },

    // У РМ один магазин
    single() {
      return !!this.manager && this.totals.length === 1
    },

    // id менеджера из адреса; на главной его нет
    managerId() {
      return this.$route.name === 'manager' ? this.$route.params.id : null
    },
  },

  // Страница выбирает область данных до отрисовки блоков и при переходе с одного РМ на другого
  created() {
    useScopeStore().use(this.managerId)
  },

  watch: {
    managerId(id) {
      useScopeStore().use(id)
    },
  },

  methods: {
    openTrend(metric) {
      this.trendMetric = metric
      this.trendOpen = true
    },
  },
}
</script>

<style lang="scss" scoped>
.home {
  // Максимальная ширина блоков сравнения. На странице РМ строк много (магазины), поэтому блокам дана почти вся ширина
  --page-max: 1500px;

  // Блоки страницы стоят по центру области контента друг под другом
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: $spacer * 10;

  &__cards {
    // Все карточки одного размера. Flex с переносом центрирует и неполный последний ряд
    --kpi-width: 360px;
    --kpi-height: 312px;

    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-content: center;
    gap: $spacer * 6;
    width: 100%;
  }

  &--stores {
    --page-max: 2600px;
  }

  // Сетка компактной страницы РМ с одним магазином: по два блока в ряд, на планшете и телефоне по одному
  &__compact {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: $spacer * 6;
    width: 100%;
    max-width: var(--page-max, 1500px);
  }

  // Нет данных за выбранный период
  &--empty {
    align-items: center;
    justify-content: center;
    gap: $spacer * 3;
    min-height: 320px;
    color: rgba(var(--v-theme-on-surface), 0.55);
    text-align: center;
  }

  &__empty-text {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
  }

  // Карточки каналов продаж: две широкие в ряд, одного размера
  &__channels {
    --channel-width: 560px;
    --channel-height: 330px;

    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: $spacer * 6;
    width: 100%;
  }

  &__channel {
    flex: 0 0 var(--channel-width);
    width: var(--channel-width);
    // На узком планшете карточка не шире области контента
    max-width: 100%;
    min-height: var(--channel-height);
  }

  // Два блока в одной строке: каждый не уже 460 px, иначе переходят в столбик
  &__pair {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(460px, 100%), 1fr));
    gap: $spacer * 6;
    width: 100%;
    max-width: var(--page-max, 1500px);
  }

  &__card {
    flex: 0 0 var(--kpi-width);
    width: var(--kpi-width);
    min-height: var(--kpi-height);
  }

  @include tablet-down {
    &__cards,
    &__channels {
      gap: $spacer * 4;
    }

    &__compact {
      grid-template-columns: minmax(0, 1fr);
      gap: $spacer * 4;
    }
  }

  // На телефоне карточка занимает всю ширину экрана
  @include phone {
    &__cards {
      --kpi-height: 284px;
    }

    &__card,
    &__channel {
      flex-basis: 100%;
      width: 100%;
    }

    &__channels {
      --channel-height: 0px;
    }
  }
}
</style>
