import { defineStore } from 'pinia'
import { API, MANAGERS } from '@/configurations'
import { fetchManager } from '@/services/managers'

const retryTimers = {}

function emptySource() {
  // status: idle — не запрашивали, loading — первая загрузка, ready — данные есть, error — данных нет, повторяем
  // refreshing — идёт ручное обновление уже загруженных данных
  return { rows: [], totals: {}, stores: {}, times: [], status: 'idle', busy: false, refreshing: false }
}

// Таблица менеджера идёт периодами подряд. В каждом периоде первая строка — итог менеджера, остальные — его магазины
// (столбец company). Возвращает итоги и магазины по периодам и список периодов в порядке таблицы.
function groupRows(rows) {
  const totals = {}
  const stores = {}
  const times = []
  for (const row of rows) {
    if (!(row.time in totals)) {
      totals[row.time] = row
      stores[row.time] = []
      times.push(row.time)
    } else {
      stores[row.time].push(row)
    }
  }
  return { totals, stores, times }
}

export const useManagersStore = defineStore('managers', {
  // Источники создаются из MANAGERS: новый менеджер в конфигурации подхватывается без правок здесь
  state: () => ({
    sources: Object.fromEntries(MANAGERS.map((manager) => [manager.id, emptySource()])),
  }),

  getters: {
    // Менеджеры с состоянием загрузки и всеми строками их таблиц
    list: (state) => MANAGERS.map((manager) => ({ ...manager, ...(state.sources[manager.id] || emptySource()) })),
  },

  actions: {
    applyRows(source, rows) {
      source.rows = rows
      Object.assign(source, groupRows(rows))
    },

    // Пока данных менеджера нет, запрос повторяется каждые API.RETRY_MS; если данные уже есть, сбой обновления не мешает
    async load(id) {
      const manager = MANAGERS.find((item) => item.id === id)
      if (!manager) return
      if (!this.sources[id]) this.sources[id] = emptySource()
      const source = this.sources[id]
      if (source.busy) return

      clearTimeout(retryTimers[id])
      source.busy = true
      if (source.status === 'idle') source.status = 'loading'
      try {
        this.applyRows(source, await fetchManager(manager))
        source.status = 'ready'
      } catch {
        if (source.status !== 'ready') {
          source.status = 'error'
          retryTimers[id] = setTimeout(() => this.load(id), API.RETRY_MS)
        }
      } finally {
        source.busy = false
      }
    },

    // Загружает указанных менеджеров одновременно; без списка — всех из конфигурации
    loadAll(ids = MANAGERS.map((manager) => manager.id)) {
      return Promise.all(ids.map((id) => this.load(id)))
    },

    // Ручное обновление: перечитывает таблицу менеджера. Возвращает true, если получилось. Сбой оставляет старые данные
    async refresh(id) {
      const manager = MANAGERS.find((item) => item.id === id)
      const source = this.sources[id]
      if (!manager || !source || source.busy) return false

      source.busy = true
      source.refreshing = true
      try {
        this.applyRows(source, await fetchManager(manager))
        source.status = 'ready'
        return true
      } catch {
        return false
      } finally {
        source.busy = false
        source.refreshing = false
      }
    },

    cancelRetry() {
      Object.values(retryTimers).forEach(clearTimeout)
    },
  },
})
