<template>
  <div class="date" :class="[`date--${phase}`, isWorkday ? 'date--workday' : 'date--weekend']">
    <div class="date__card">
      <span class="date__day">{{ day }}</span>
      <span class="date__text">
        <span class="date__month">{{ month }} {{ year }}</span>
        <span class="date__weekday">{{ weekday }}</span>
      </span>
    </div>

    <transition name="date-mode" mode="out-in">
      <div v-if="showScale" key="scale" class="date__scale">
        <div class="date__row">
          <span class="date__status">
            <span class="date__pulse" aria-hidden="true"></span>
            <transition name="date-swap" mode="out-in">
              <span :key="phase" class="date__status-text">{{ $t(`day.${phase}`) }}</span>
            </transition>
          </span>
          <span class="date__time">{{ time }}</span>
        </div>

        <div
          class="date__track"
          role="progressbar"
          aria-valuemin="0"
          aria-valuemax="100"
          :aria-valuenow="Math.round(percent)"
          :aria-label="$t(`day.${phase}`)"
        >
          <span class="date__fill" :style="{ width: `${shown}%` }"></span>

          <span class="date__lunch" :style="{ left: `${lunchLeft}%`, width: `${lunchWidth}%` }">
            <v-icon :icon="mdiSilverwareForkKnife" size="10" />
            <v-tooltip activator="parent" location="bottom" :text="lunchText" />
          </span>

          <span class="date__marker" :style="{ left: `${shown}%` }"></span>
        </div>

        <div class="date__row date__row--ticks">
          <span>{{ hourLabel(start) }}</span>
          <span class="date__lunch-time" :style="{ left: `${lunchLeft + lunchWidth / 2}%` }">
            {{ hourLabel(lunchStart) }}–{{ hourLabel(lunchEnd) }}
          </span>
          <span>{{ hourLabel(end) }}</span>
        </div>
      </div>

      <div v-else key="clock" class="date__clock" role="timer" :aria-label="time">
        <template v-for="(part, index) in timeParts" :key="index">
          <span v-if="index" class="date__colon">:</span>{{ part }}
        </template>
      </div>
    </transition>
  </div>
</template>

<script>
import { mdiSilverwareForkKnife } from '@mdi/js'
import { WORKDAY } from '@/configurations'

const TICK_MS = 1000

function pad(value) {
  return String(value).padStart(2, '0')
}

export default {
  name: 'HeaderDate',

  data() {
    return {
      mdiSilverwareForkKnife,
      now: new Date(),
      // Сначала шкала пустая, после появления плавно заполняется
      ready: false,
      start: WORKDAY.START,
      end: WORKDAY.END,
      lunchStart: WORKDAY.LUNCH_START,
      lunchEnd: WORKDAY.LUNCH_END,
    }
  },

  computed: {
    locale() {
      return this.$i18n.locale
    },

    day() {
      return pad(this.now.getDate())
    },

    month() {
      return new Intl.DateTimeFormat(this.locale, { month: 'long' }).format(this.now)
    },

    year() {
      return this.now.getFullYear()
    },

    weekday() {
      const name = new Intl.DateTimeFormat(this.locale, { weekday: 'long' }).format(this.now)
      return name.charAt(0).toUpperCase() + name.slice(1)
    },

    timeParts() {
      return [this.now.getHours(), this.now.getMinutes(), this.now.getSeconds()].map(pad)
    },

    // Будний день по настройке WORKDAY.DAYS; праздники не учитываются
    isWorkday() {
      return WORKDAY.DAYS.includes(this.now.getDay())
    },

    // Шкала дня нужна только в рабочие дни и до конца рабочего вечера; потом остаются крупные часы
    showScale() {
      return this.isWorkday && this.hours < WORKDAY.HIDE_AFTER
    },

    time() {
      return `${pad(this.now.getHours())}:${pad(this.now.getMinutes())}:${pad(this.now.getSeconds())}`
    },

    // Текущее время в часах, например 12.5 = 12:30
    hours() {
      return this.now.getHours() + this.now.getMinutes() / 60 + this.now.getSeconds() / 3600
    },

    span() {
      return this.end - this.start
    },

    percent() {
      return Math.min(100, Math.max(0, ((this.hours - this.start) / this.span) * 100))
    },

    shown() {
      return this.ready ? this.percent : 0
    },

    lunchLeft() {
      return ((WORKDAY.LUNCH_START - this.start) / this.span) * 100
    },

    lunchWidth() {
      return ((WORKDAY.LUNCH_END - WORKDAY.LUNCH_START) / this.span) * 100
    },

    lunchText() {
      return this.$t('day.lunchHours', {
        from: this.hourLabel(this.lunchStart),
        to: this.hourLabel(this.lunchEnd),
      })
    },

    // before — до открытия, work — рабочее время, lunch — обед, after — после закрытия
    phase() {
      if (this.hours < this.start) return 'before'
      if (this.hours >= this.end) return 'after'
      if (this.hours >= WORKDAY.LUNCH_START && this.hours < WORKDAY.LUNCH_END) return 'lunch'
      return 'work'
    },
  },

  mounted() {
    this.timer = setInterval(() => {
      this.now = new Date()
    }, TICK_MS)
    this.readyTimer = setTimeout(() => (this.ready = true), 100)
  },

  beforeUnmount() {
    clearInterval(this.timer)
    clearTimeout(this.readyTimer)
  },

  methods: {
    hourLabel(hour) {
      return `${pad(hour)}:00`
    },
  },
}
</script>

