import { API, NBU } from '@/configurations'

// Сегодняшняя дата в формате ГГГГММДД. Без неё НБУ отдаёт курс, который начнёт действовать
// со следующего рабочего дня (в пятницу и на выходных это понедельник).
function today() {
  const now = new Date()
  const month = String(now.getMonth() + 1).padStart(2, '0')
  const day = String(now.getDate()).padStart(2, '0')
  return `${now.getFullYear()}${month}${day}`
}

// Официальные курсы НБУ к гривне на сегодня для валют из NBU.CURRENCIES.
// Возвращает { date: 'ДД.ММ.ГГГГ', rates: { USD: 44.67, ... } }; при сбое бросает ошибку.
export async function fetchRates() {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), API.TIMEOUT)

  try {
    const response = await fetch(`${NBU.URL}&date=${today()}`, { signal: controller.signal })
    if (!response.ok) throw new Error(`NBU ${response.status}`)

    const list = await response.json()
    const rates = {}
    let date = ''
    for (const { code } of NBU.CURRENCIES) {
      const item = list.find((entry) => entry.cc === code)
      if (!item || typeof item.rate !== 'number') throw new Error(`NBU: нет курса ${code}`)
      rates[code] = item.rate
      date = item.exchangedate
    }
    return { date, rates }
  } finally {
    clearTimeout(timer)
  }
}
