<template>
  <section class="itm" :class="{ 'itm--dense': dense }" :aria-label="$t('items.title')">
    <panel-head :icon="mdiBasketOutline" :title="$t('items.title')" :period="period" />

    <ul class="itm__legend">
      <li><span class="itm__swatch itm__swatch--fact"></span>{{ $t('kpi.fact') }}</li>
      <li><span class="itm__swatch itm__swatch--plan"></span>{{ $t('kpi.plan') }}</li>
      <li><span class="itm__swatch itm__swatch--past"></span>{{ $t('traffic.pastShort') }}</li>
    </ul>

    <!-- Корзина наполняется до среднего количества позиций в чеке; полная корзина = верх шкалы -->
    <ul class="itm__rows">
      <li v-for="(item, index) in items" :key="item.manager.id" class="itm__row" :style="{ '--mc': item.rgb, '--i': index }">
        <svg class="itm__svg" viewBox="-8 0 116 104" role="img" :aria-label="`${item.manager.name}: ${number(item.fact, 2)}`">
          <defs>
            <clipPath :id="`${uid}-clip-${index}`">
              <path :d="BASKET" />
            </clipPath>
            <linearGradient :id="`${uid}-grad-${index}`" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" class="itm__stop itm__stop--top" />
              <stop offset="1" class="itm__stop" />
            </linearGradient>
          </defs>

          <!-- Ручка и пустая корзина -->
          <path class="itm__handle" d="M30 34 C30 6 70 6 70 34" />
          <path class="itm__basket" :d="BASKET" />

          <!-- «Жидкость» с двумя волнами внутри корзины -->
          <g :clip-path="`url(#${uid}-clip-${index})`">
            <g class="itm__liquid" :style="{ transform: `translateY(${top(item.fact)}px)` }">
              <g class="itm__wave itm__wave--back"><path :d="WAVE" class="itm__back" /></g>
              <g class="itm__wave"><path :d="WAVE" :fill="`url(#${uid}-grad-${index})`" /></g>
            </g>
            <!-- Плетение корзины поверх заливки -->
            <path class="itm__weave" d="M34 34 L37 96 M50 34 L50 96 M66 34 L63 96 M10 56 H90 M14 76 H86" />
          </g>

          <path class="itm__rim" d="M4 30 H96" />

          <!-- План — пунктирная линия через всю корзину, прошлый год — точка справа -->
          <line v-if="item.plan !== null" class="itm__plan" x1="-4" x2="104" :y1="top(item.plan)" :y2="top(item.plan)" />
          <circle v-if="item.past !== null" class="itm__past" cx="100" r="4" :cy="top(item.past)" />
        </svg>

        <div class="itm__info">
          <span class="itm__name">
            <i class="itm__dot" aria-hidden="true"></i>
            {{ item.manager.name }}
          </span>

          <div class="itm__sub">
            <span v-if="item.past !== null">{{ $t('traffic.pastShort') }} {{ number(item.past, 2) }}</span>
            <b v-if="item.delta !== null" class="itm__delta" :class="item.delta >= 0 ? 'itm__delta--good' : 'itm__delta--bad'">
              {{ item.delta >= 0 ? '▲' : '▼' }} {{ number(Math.abs(item.delta), 0) }}% <span class="itm__vs">{{ $t('kpi.vsPast') }}</span>
            </b>
          </div>
        </div>

        <div class="itm__result">
          <b class="itm__value">{{ number(item.fact, 2) }}</b>
          <span v-if="item.plan !== null" class="itm__plan-text">{{ $t('kpi.plan') }} <b>{{ number(item.plan, 2) }}</b></span>
          <b v-if="item.percent !== null" class="itm__pill" :class="`itm__pill--${item.state}`">{{ number(item.percent, 1) }}%</b>
        </div>
      </li>
    </ul>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiBasketOutline } from '@mdi/js'
import PanelHead from '@/components/PanelHead.vue'
import { useScopeStore } from '@/stores/scope'
import { DENSE_FROM, completion, growth, statusOf } from '@/utils/kpi'
import { entryRgb } from '@/utils/color'

// Корзина в координатах SVG: внутренняя область по высоте от 30 (край) до 96 (дно)
const RIM = 30
const BOTTOM = 96
let counter = 0
const BASKET = 'M6 30 H94 L84 91 Q83 96 78 96 H22 Q17 96 16 91 Z'
// Волна с периодом 50: сдвиг на 50 по оси X даёт бесшовную анимацию
const WAVE = 'M0 3 Q12.5 -3 25 3 T50 3 T75 3 T100 3 T125 3 T150 3 T175 3 T200 3 V120 H0 Z'

export default {
  name: 'ItemsByManagers',

  components: { PanelHead },

  data() {
    return {
      mdiBasketOutline,
      BASKET,
      WAVE,
      // Корзины наполняются после появления блока
      ready: false,
      // Уникальная основа id внутри SVG
      uid: `itm${++counter}`,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['current', 'kind']),
    ...mapState(useScopeStore, ['totals']),

    locale() {
      return this.$i18n.locale
    },

    // Много строк (магазины): строки компактные
    dense() {
      return this.totals.length > DENSE_FROM
    },

    period() {
      return this.current ? this.current.time : ''
    },

    // Менеджеры от большего количества позиций к меньшему
    items() {
      const list = this.totals.map(({ manager, row }) => {
        const pick = (field) => (row && typeof row[field] === 'number' ? row[field] : null)
        const fact = pick('count_f')
        const plan = pick('count_p')
        const past = pick('count_past')
        const percent = completion(fact, plan)
        return { manager, rgb: entryRgb(this.kind, manager, statusOf(percent)), fact, plan, past, percent, state: statusOf(percent), delta: growth(fact, past) }
      })
      return list.sort((a, b) => (b.fact === null ? -1 : b.fact) - (a.fact === null ? -1 : a.fact))
    },

    // Полная корзина: целое число позиций, в которое влезают все значения (обычно две)
    scale() {
      const values = this.items.flatMap((item) => [item.fact, item.plan, item.past]).filter((value) => typeof value === 'number')
      return Math.max(2, Math.ceil(Math.max(0, ...values)))
    },
  },

  mounted() {
    this.readyTimer = setTimeout(() => (this.ready = true), 350)
  },

  beforeUnmount() {
    clearTimeout(this.readyTimer)
  },

  methods: {
    number(value, digits) {
      if (typeof value !== 'number') return '—'
      return new Intl.NumberFormat(this.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value)
    },

    // Высота уровня в координатах SVG; пока блок не появился, всё лежит на дне
    top(value) {
      if (!this.ready || typeof value !== 'number') return BOTTOM
      return BOTTOM - Math.min(1, value / this.scale) * (BOTTOM - RIM)
    },
  },
}
</script>

