<template>
  <section class="mgr" :class="{ 'mgr--dense': dense, 'mgr--slanted': slanted, 'mgr--narrow': narrow }" :style="chartStyle" :aria-label="heading">
    <header class="mgr__head">
      <span class="mgr__icon" aria-hidden="true">
        <v-icon :icon="chart.icon" size="26" />
      </span>

      <div class="mgr__heading">
        <h2 class="mgr__title">{{ heading }}</h2>
        <span v-if="period" class="mgr__period">
          <i class="mgr__dot" aria-hidden="true"></i>
          {{ period }}
        </span>
      </div>

      <ul class="mgr__legend">
        <li><span class="mgr__swatch mgr__swatch--fact"></span>{{ $t('kpi.fact') }}</li>
        <li><span class="mgr__swatch" :class="`mgr__swatch--${compareKind}`"></span>{{ compareLabel }}</li>
        <li><span class="mgr__swatch mgr__swatch--plan"></span>{{ $t('kpi.plan') }}</li>
      </ul>
    </header>

    <div ref="body" class="mgr__body">
    <div v-if="!compact" class="mgr__scroll">
      <div class="mgr__chart">
        <!-- Одна ось: гривны. Процент выполнения показан бейджем, а не второй осью -->
        <div class="mgr__axis" aria-hidden="true">
          <span v-for="tick in ticks" :key="tick.value" class="mgr__tick" :style="{ bottom: `${tick.pct}%` }">{{ tick.label }}</span>
        </div>

        <div class="mgr__plot">
          <div class="mgr__lines" aria-hidden="true">
            <span v-for="tick in ticks" :key="tick.value" class="mgr__line" :style="{ bottom: `${tick.pct}%` }"></span>
          </div>

          <div
            v-for="(item, index) in items"
            :key="item.manager.id"
            class="mgr__group"
            :class="[`mgr__group--${item.state}`, { 'mgr__group--active': active === index }]"
            :style="{ '--i': index }"
            tabindex="0"
            @pointerenter="active = index"
            @pointerleave="active = -1"
            @focus="active = index"
            @blur="active = -1"
          >
            <div class="mgr__bars">
              <div v-if="item.fact !== null" class="mgr__pair">
                <!-- Факт: значение внутри колонки, процент выполнения внизу, чёрточка плана поперёк -->
                <div class="mgr__col">
                  <div v-if="item.small || narrow" class="mgr__label" :style="{ bottom: `calc(${shown(Math.max(item.fact, item.plan || 0))}% + 8px)` }">
                    <span class="mgr__value mgr__value--out"><b>{{ number(item.fact / 1e6, 2) }}</b><small>{{ $t('kpi.million') }}</small></span>
                    <span v-if="item.percent !== null" class="mgr__pill">{{ number(item.percent, 1) }}%</span>
                  </div>

                  <div class="mgr__bar mgr__bar--fact" :style="{ height: `${shown(item.fact)}%` }">
                    <template v-if="!item.small && !narrow">
                      <span class="mgr__value"><b>{{ number(item.fact / 1e6, 2) }}</b><small>{{ $t('kpi.million') }}</small></span>
                      <span v-if="item.percent !== null" class="mgr__pill mgr__pill--in">{{ number(item.percent, 1) }}%</span>
                    </template>
                  </div>

                  <span v-if="item.plan !== null" class="mgr__plan" :style="{ bottom: `${shown(item.plan)}%` }" aria-hidden="true"></span>
                </div>

                <!-- Колонка сравнения: факт прошлого года или весь товарооборот -->
                <div v-if="item.compare !== null" class="mgr__col">
                  <div class="mgr__label mgr__label--past" :style="{ bottom: `calc(${shown(item.compare)}% + 6px)` }">
                    <span v-if="item.badge" class="mgr__chip" :class="`mgr__chip--${item.badge.kind}`">
                      <i v-if="item.badge.arrow" aria-hidden="true">{{ item.badge.arrow }}</i>
                      {{ item.badge.text }}
                    </span>
                    <b>{{ million(item.compare) }}</b>
                  </div>
                  <div class="mgr__bar" :class="`mgr__bar--${compareKind}`" :style="{ height: `${shown(item.compare)}%` }"></div>
                </div>
              </div>

              <span v-else class="mgr__empty">—</span>
            </div>

            <div class="mgr__name">
              <i class="mgr__manager" :style="{ background: item.dot }" aria-hidden="true"></i>
              <span class="mgr__name-text">{{ item.manager.name }}</span>
            </div>

            <transition name="mgr-tip">
              <div v-if="active === index && item.fact !== null" class="mgr__tip" :class="tipClass(index)" role="tooltip">
                <strong>{{ item.manager.name }}</strong>
                <dl>
                  <div v-if="item.percent !== null" class="mgr__tip-main">
                    <dt>{{ $t('kpi.planCompletion') }}</dt>
                    <dd>{{ number(item.percent, 1) }}%</dd>
                  </div>
                  <div>
                    <dt>{{ $t('kpi.fact') }}</dt>
                    <dd>{{ full(item.fact) }}</dd>
                  </div>
                  <div v-if="item.plan !== null">
                    <dt>{{ $t('kpi.plan') }}</dt>
                    <dd>{{ full(item.plan) }}</dd>
                  </div>
                  <div v-if="item.compare !== null">
                    <dt>{{ compareLabel }}</dt>
                    <dd>{{ full(item.compare) }}</dd>
                  </div>
                  <div v-if="item.badge">
                    <dt>{{ chart.mode === 'total' ? $t('kpi.shareOfTotal') : $t('kpi.vsPast') }}</dt>
                    <dd>{{ item.badge.tip }}</dd>
                  </div>
                </dl>
              </div>
            </transition>
          </div>
        </div>
      </div>
    </div>

    <!-- Узкий блок: вертикальный список, по строке на менеджера, полосы идут вправо и всегда помещаются -->
    <div v-else class="mgr__rows-wrap">
      <ul class="mgr__rows">
        <li v-for="(item, index) in items" :key="item.manager.id" class="mgr__row" :class="`mgr__row--${item.state}`" :style="{ '--i': index }">
          <div class="mgr__row-head">
            <span class="mgr__row-name">
              <i class="mgr__manager" :style="{ background: item.dot }" aria-hidden="true"></i>
              {{ item.manager.name }}
            </span>
            <span v-if="item.badge" class="mgr__chip" :class="`mgr__chip--${item.badge.kind}`">
              <i v-if="item.badge.arrow" aria-hidden="true">{{ item.badge.arrow }}</i>
              {{ item.badge.text }}
            </span>
            <b class="mgr__row-pill">{{ item.percent === null ? '—' : `${number(item.percent, 1)}%` }}</b>
          </div>

          <div v-if="item.fact !== null" class="mgr__track">
            <span v-for="tick in ticks" :key="tick.value" class="mgr__vline" :style="{ left: `${tick.pct}%` }" aria-hidden="true"></span>

            <!-- Факт -->
            <div class="mgr__hrow">
              <div class="mgr__hbar mgr__hbar--fact" :style="{ width: `${shown(item.fact)}%` }">
                <span v-if="inside(item.fact, 26)" class="mgr__hval">{{ million(item.fact) }}</span>
              </div>
              <span v-if="!inside(item.fact, 26)" class="mgr__hval mgr__hval--out" :style="{ left: `calc(${shown(Math.max(item.fact, item.plan || 0))}% + 8px)` }">{{ million(item.fact) }}</span>
            </div>

            <!-- Полоса сравнения: факт прошлого года или весь товарооборот -->
            <div v-if="item.compare !== null" class="mgr__hrow mgr__hrow--past">
              <div class="mgr__hbar" :class="`mgr__hbar--${compareKind}`" :style="{ width: `${shown(item.compare)}%` }">
                <span v-if="inside(item.compare, 24)" class="mgr__hval mgr__hval--past">{{ million(item.compare) }}</span>
              </div>
              <span v-if="!inside(item.compare, 24)" class="mgr__hval mgr__hval--past mgr__hval--out" :style="{ left: `calc(${shown(Math.max(item.compare, item.plan || 0))}% + 8px)` }">{{ million(item.compare) }}</span>
            </div>

            <!-- План: вертикальная чёрточка через обе полосы -->
            <span v-if="item.plan !== null" class="mgr__hplan" :style="{ left: `${shown(item.plan)}%` }" aria-hidden="true"></span>
          </div>
          <span v-else class="mgr__empty">—</span>

          <span v-if="item.plan !== null" class="mgr__meta">{{ $t('kpi.plan') }}: {{ million(item.plan) }}</span>
        </li>
      </ul>

      <!-- Шкала в гривнах под всеми строками -->
      <div class="mgr__scale" aria-hidden="true">
        <span
          v-for="(tick, index) in ticks"
          :key="tick.value"
          class="mgr__scale-tick"
          :class="{ 'mgr__scale-tick--last': index === ticks.length - 1 }"
          :style="{ left: `${tick.pct}%` }"
        >
          {{ tick.label }}
        </span>
      </div>
    </div>
    </div>

    <!-- Итог по каждому менеджеру одной строкой -->
    <ul v-if="!compact" class="mgr__summary">
      <li v-for="item in items" :key="item.manager.id" class="mgr__tag" :class="`mgr__tag--${item.state}`">
        <i class="mgr__manager" :style="{ background: item.dot }" aria-hidden="true"></i>
        {{ item.manager.name }}
        <b>{{ item.percent === null ? '—' : `${number(item.percent, 1)}%` }}</b>
      </li>
    </ul>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { useScopeStore } from '@/stores/scope'
import { completion, growth, MANAGER_CHARTS, statusOf } from '@/utils/kpi'
import { entryRgb } from '@/utils/color'

// Сколько места нужно графику с колонками (px): ось, отступы и минимальная ширина каждой группы (две колонки по 60 px,
// зазор и выступ чёрточки плана). Значения совпадают со стилями ниже. Если блок уже, появилась бы полоса прокрутки:
// вместо колонок показывается вертикальный список.
const AXIS_WIDTH = 62
const GRID_GAP = 12
const PLOT_PADDING = 12
// Ниже этой ширины области (телефон) вместо колонок вертикальный список: строка на менеджера, полосы идут вправо
const PHONE_WIDTH = 560
// Группе (факт + прошлый год) нужно хотя бы столько px, иначе колонки не различить и тоже вертикальный список
const MIN_GROUP = 62
// Группа уже этого (много магазинов): все данные остаются, но шрифты мельче
const DENSE_GROUP = 150
// Группа уже этого: названия под углом, чтобы не налезали друг на друга
const SLANTED_GROUP = 130
// Колонка уже этого (px): совсем тесно, значения только над колонкой факта, без процента и подписей прошлого года
const NARROW_COLUMN = 34

// Колонка ниже этого процента высоты слишком низкая для значения и бейджа внутри: они уходят наверх
const SMALL_BAR = 30

// Округляет верх шкалы так, чтобы линии сетки попадали на «круглые» числа (в гривнах)
function niceScale(max) {
  if (!(max > 0)) return { top: 1, step: 1 }
  const rough = max / 4
  const power = Math.pow(10, Math.floor(Math.log10(rough)))
  const step = [1, 2, 2.5, 5, 10].map((k) => k * power).find((value) => value >= rough)
  return { top: Math.ceil(max / step) * step, step }
}

export default {
  name: 'ManagersPlanChart',

  props: {
    // Описание графика из MANAGER_CHARTS: какие поля брать и с чем сравнивать факт
    chart: {
      type: Object,
      default: () => MANAGER_CHARTS[0],
    },
  },

  data() {
    return {
      // Колонки растут от нуля после появления блока
      ready: false,
      active: -1,
      // Ширина области графика, px; 0 — ещё не измерена
      bodyWidth: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['current', 'kind']),
    ...mapState(useScopeStore, ['totals']),

    locale() {
      return this.$i18n.locale
    },

    // Ширина одной группы колонок: область графика делится поровну между менеджерами или магазинами
    groupWidth() {
      const available = this.bodyWidth - AXIS_WIDTH - GRID_GAP - PLOT_PADDING
      return this.totals.length ? available / this.totals.length : Infinity
    },

    // Телефон, совсем тесно или всего одна запись (один магазин): вместо колонок горизонтальные полосы
    compact() {
      return this.totals.length < 2 || (this.bodyWidth > 0 && (this.bodyWidth < PHONE_WIDTH || this.groupWidth < MIN_GROUP))
    },

    // Ширина одной колонки: 60 px, а при большом числе групп уже, чтобы все поместились без прокрутки
    columnWidth() {
      return this.bodyWidth > 0 ? Math.max(18, Math.min(60, Math.floor((this.groupWidth - 20) / 2 - 2))) : 60
    },

    // Колонок много: шрифты и отступы мельче, данные те же
    dense() {
      return !this.compact && this.bodyWidth > 0 && this.groupWidth < DENSE_GROUP
    },

    // Названия под углом, когда группы уже названий
    slanted() {
      return !this.compact && this.bodyWidth > 0 && this.groupWidth < SLANTED_GROUP
    },

    // Колонки совсем тонкие: остаётся только значение над колонкой факта
    narrow() {
      return !this.compact && this.columnWidth < NARROW_COLUMN
    },

    chartStyle() {
      return { '--col': `${this.columnWidth}px` }
    },

    // Название графика: у страницы РМ то же, но про магазины (ключ с суффиксом Stores)
    heading() {
      return this.$t(this.kind === 'stores' ? `${this.chart.titleKey}Stores` : this.chart.titleKey)
    },

    period() {
      return this.current ? this.current.time : ''
    },

    // past — колонка прошлого года (штриховка), total — весь товарооборот (сплошная серая)
    compareKind() {
      return this.chart.mode === 'total' ? 'total' : 'past'
    },

    compareLabel() {
      return this.chart.mode === 'total' ? this.$t('kpi.products') : this.$t('kpi.factPast')
    },

    // Менеджеры от большего товарооборота к меньшему; у кого нет данных за период — в конце
    items() {
      const list = this.totals.map(({ manager, row }) => {
        const pick = (field) => (row && typeof row[field] === 'number' ? row[field] : null)
        const fact = pick(this.chart.fact)
        const plan = pick(this.chart.plan)
        const compare = pick(this.chart.compare)
        const percent = completion(fact, plan)
        const heightPct = fact === null ? 0 : (fact / this.scale.top) * 100
        return {
          manager,
          // Точка у названия: у менеджера его цвет, у магазина цвет выполнения плана
          dot: this.kind === 'stores' ? `rgb(${entryRgb(this.kind, manager, statusOf(percent))})` : manager.color,
          fact,
          plan,
          compare,
          percent,
          badge: this.badge(fact, compare),
          state: statusOf(percent),
          small: heightPct < SMALL_BAR,
        }
      })
      return list.sort((a, b) => (b.fact === null ? -1 : b.fact) - (a.fact === null ? -1 : a.fact))
    },

    // Масштаб общий для всех колонок: по максимуму из факта, плана и прошлого года
    scale() {
      const values = this.totals.flatMap(({ row }) =>
        row ? [row[this.chart.fact], row[this.chart.plan], row[this.chart.compare]].filter((value) => typeof value === 'number') : [],
      )
      return niceScale(Math.max(0, ...values))
    },

    ticks() {
      const { top, step } = this.scale
      const decimals = step >= 1e6 ? 0 : 1
      const ticks = []
      for (let value = 0; value <= top + step / 1000; value += step) {
        ticks.push({
          value,
          pct: (value / top) * 100,
          label: value === 0 ? '0' : `${this.number(value / 1e6, decimals)} ${this.$t('kpi.million')}`,
        })
      }
      return ticks
    },
  },

  mounted() {
    this.readyTimer = setTimeout(() => (this.ready = true), 350)

    // Следим за шириной области графика: она меняется при повороте экрана, сворачивании сайдбара и т. п.
    this.measure()
    if ('ResizeObserver' in window) {
      this.observer = new ResizeObserver(this.measure)
      this.observer.observe(this.$refs.body)
    }
  },

  beforeUnmount() {
    clearTimeout(this.readyTimer)
    if (this.observer) this.observer.disconnect()
  },

  methods: {
    // Бейдж у колонки сравнения: рост к прошлому году (▲ +35%) или доля факта во всём товарообороте (79%)
    badge(fact, compare) {
      if (this.chart.mode === 'total') {
        if (fact === null || !compare) return null
        const share = Math.round((fact / compare) * 100)
        return { kind: 'share', text: `${share}%`, tip: `${share}%` }
      }
      const delta = growth(fact, compare)
      if (delta === null) return null
      const text = `${delta >= 0 ? '+' : ''}${Math.round(delta)}%`
      return { kind: delta >= 0 ? 'up' : 'down', arrow: delta >= 0 ? '▲' : '▼', text, tip: text }
    },

    measure() {
      if (this.$refs.body) this.bodyWidth = this.$refs.body.clientWidth
    },

    number(value, digits) {
      if (typeof value !== 'number') return '—'
      return new Intl.NumberFormat(this.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value)
    },

    // «19,78 млн»
    million(value) {
      return `${this.number(value / 1e6, 2)} ${this.$t('kpi.million')}`
    },

    // Полная сумма в гривнах для подсказки
    full(value) {
      return `${this.number(value, 0)} ${this.$t('kpi.uah')}`
    },

    // Хватает ли полосе длины, чтобы значение поместилось внутри (min — доля шкалы в процентах)
    inside(value, min) {
      return typeof value === 'number' && (value / this.scale.top) * 100 >= min
    },

    // Высота в процентах шкалы; пока блок не появился, колонки нулевые
    shown(value) {
      return this.ready && typeof value === 'number' ? (value / this.scale.top) * 100 : 0
    },

    // В правой половине графика подсказка открывается влево
    tipClass(index) {
      return index >= Math.ceil(this.items.length / 2) ? 'mgr__tip--left' : ''
    },
  },
}
</script>

