import { defineStore } from 'pinia'
import { LOCALES, STORAGE_KEYS, THEMES } from '@/configurations'
import { readStorage, writeStorage } from '@/utils/storage'

const themeNames = Object.keys(THEMES.AVAILABLE)
const localeCodes = LOCALES.AVAILABLE.map((locale) => locale.code)

function pick(value, allowed, fallback) {
  return allowed.includes(value) ? value : fallback
}

export const useSettingsStore = defineStore('settings', {
  state: () => ({
    theme: pick(readStorage(STORAGE_KEYS.THEME), themeNames, THEMES.DEFAULT),
    locale: pick(readStorage(STORAGE_KEYS.LOCALE), localeCodes, LOCALES.DEFAULT),
  }),

  getters: {
    isDark: (state) => THEMES.AVAILABLE[state.theme].dark,
    themes: () => themeNames,
    locales: () => LOCALES.AVAILABLE,
  },

  actions: {
    setTheme(theme) {
      this.theme = pick(theme, themeNames, THEMES.DEFAULT)
      writeStorage(STORAGE_KEYS.THEME, this.theme)
    },

    toggleTheme() {
      this.setTheme(this.isDark ? 'light' : 'dark')
    },

    setLocale(locale) {
      this.locale = pick(locale, localeCodes, LOCALES.DEFAULT)
      writeStorage(STORAGE_KEYS.LOCALE, this.locale)
    },
  },
})
