<template>
  <section class="sit" :aria-label="$t('analytics.title')">
    <panel-head :icon="mdiHeartPulse" :title="$t('analytics.title')" :period="period" />

    <div class="sit__layout">
      <!-- Слева итог: доля показателей с выполненным планом, счётчики и сильные/слабые места -->
      <aside class="sit__summary" :class="`sit__summary--${verdict}`">
        <div class="sit__ring">
          <svg viewBox="0 0 120 120" aria-hidden="true">
            <circle class="sit__ring-track" cx="60" cy="60" r="50" />
            <circle class="sit__ring-fill" cx="60" cy="60" r="50" :stroke-dasharray="`${ringLength} ${CIRCLE}`" />
          </svg>
          <div class="sit__ring-text">
            <b>{{ metCount }}<small>/{{ items.length }}</small></b>
            <span>{{ $t('analytics.meetPlan') }}</span>
          </div>
        </div>

        <b class="sit__verdict">{{ $t(`analytics.verdict.${verdict}`) }}</b>

        <ul class="sit__counters">
          <li class="sit__counter sit__counter--good">
            <v-icon :icon="mdiCheckCircleOutline" size="20" />
            <span>{{ $t('analytics.meetPlan') }}</span>
            <b>{{ metCount }} {{ $t('analytics.of') }} {{ items.length }}</b>
          </li>
          <li class="sit__counter sit__counter--good">
            <v-icon :icon="mdiTrendingUp" size="20" />
            <span>{{ $t('analytics.growing') }}</span>
            <b>{{ growingCount }} {{ $t('analytics.of') }} {{ withPast }}</b>
          </li>
          <li class="sit__counter sit__counter--bad">
            <v-icon :icon="mdiTrendingDown" size="20" />
            <span>{{ $t('analytics.falling') }}</span>
            <b>{{ fallingCount }} {{ $t('analytics.of') }} {{ withPast }}</b>
          </li>
        </ul>

        <div class="sit__focus">
          <span class="sit__focus-title">{{ $t('analytics.attention') }}</span>
          <ul v-if="weak.length" class="sit__chips">
            <li v-for="item in weak" :key="item.id" class="sit__chip sit__chip--warn">
              <v-icon :icon="item.icon" size="14" />
              {{ $t(item.title) }} <b>{{ percent(item.percent) }}</b>
            </li>
          </ul>
          <span v-else class="sit__all-good">{{ $t('analytics.allGood') }}</span>
        </div>

        <div class="sit__focus">
          <span class="sit__focus-title">{{ $t('analytics.strong') }}</span>
          <ul class="sit__chips">
            <li v-for="item in strong" :key="item.id" class="sit__chip sit__chip--good">
              <v-icon :icon="item.icon" size="14" />
              {{ $t(item.title) }} <b>{{ percent(item.percent) }}</b>
            </li>
          </ul>
        </div>
      </aside>

      <!-- Справа все показатели: выполнение плана и динамика к прошлому году -->
      <div class="sit__board">
        <div class="sit__cols" aria-hidden="true">
          <span></span>
          <span>{{ $t('kpi.planCompletion') }}</span>
          <span>{{ $t('kpi.yoy') }}</span>
        </div>

        <ul class="sit__rows">
          <li v-for="(item, index) in items" :key="item.id" class="sit__row" :class="`sit__row--${item.state}`" :style="{ '--i': index }">
            <span class="sit__name">
              <span class="sit__icon"><v-icon :icon="item.icon" size="20" /></span>
