            </span>

            <div class="sit__cell">
              <span class="sit__cell-label">{{ $t('kpi.planCompletion') }}</span>
              <span class="sit__track sit__track--plan">
                <span class="sit__fill" :style="{ width: `${planWidth(item.percent)}%` }"></span>
                <i class="sit__mark" :style="{ left: `${(100 / PLAN_MAX) * 100}%` }" aria-hidden="true"></i>
              </span>
              <b class="sit__chip-value" :class="`sit__chip-value--${item.state}`">
                {{ item.percent === null ? '—' : `${item.percent >= 100 ? '▲' : '▼'} ${percent(item.percent)}` }}
              </b>
            </div>

