                <i class="sit__zero" aria-hidden="true"></i>
              </span>
              <b class="sit__chip-value" :class="item.delta === null ? 'sit__chip-value--none' : item.delta >= 0 ? 'sit__chip-value--good' : 'sit__chip-value--bad'">
                {{ item.delta === null ? '—' : `${item.delta >= 0 ? '+' : '−'}${number(Math.abs(item.delta), 0)}%` }}
              </b>
            </div>
          </li>
        </ul>
      </div>
    </div>
