</template>

<script>
import { mapState } from 'pinia'
import { mdiCheckCircleOutline, mdiHeartPulse, mdiTrendingDown, mdiTrendingUp } from '@mdi/js'
import PanelHead from '@/components/PanelHead.vue'
import { useScopeStore } from '@/stores/scope'
import { CHANNEL_METRICS, completion, growth, KPI_METRICS, statusOf } from '@/utils/kpi'

// Окружность кольца при радиусе 50
const CIRCLE = 2 * Math.PI * 50
// Шкала выполнения плана заканчивается на 130 %, роста — на ±40 %; большее значение обрезается по краю, число остаётся точным
const PLAN_MAX = 130
const YOY_MAX = 40

export default {
  name: 'SituationAnalytics',

  components: { PanelHead },

  data() {
    return {
      mdiHeartPulse,
      mdiCheckCircleOutline,
      mdiTrendingUp,
      mdiTrendingDown,
      CIRCLE,
      PLAN_MAX,
      // Полосы и кольцо заполняются после появления блока
      ready: false,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['current', 'hasChannels']),

    locale() {
      return this.$i18n.locale
    },

    period() {
      return this.current ? this.current.time : ''
    },

    // Все показатели компании: карточки и каналы продаж, от лучшего выполнения плана к худшему
    items() {
      const row = this.current
      if (!row) return []
      const pick = (field) => (field && typeof row[field] === 'number' ? row[field] : null)
      // Интернет-магазин и Мономаркет есть только у компании, на странице РМ их нет
      return [...KPI_METRICS, ...(this.hasChannels ? CHANNEL_METRICS : [])]
        .map((metric) => {
          const percent = completion(pick(metric.fact), pick(metric.plan))
          return { id: metric.id, icon: metric.icon, title: metric.title, percent, state: statusOf(percent), delta: growth(pick(metric.fact), pick(metric.past)) }
        })
        .sort((a, b) => (b.percent === null ? -1 : b.percent) - (a.percent === null ? -1 : a.percent))
    },

    metCount() {
      return this.items.filter((item) => item.percent !== null && item.percent >= 100).length
    },

    withPast() {
      return this.items.filter((item) => item.delta !== null).length
    },

    growingCount() {
      return this.items.filter((item) => item.delta !== null && item.delta >= 0).length
    },

    fallingCount() {
      return this.withPast - this.growingCount
    },

    // Показатели ниже плана: самые слабые первыми
    weak() {
      return this.items.filter((item) => item.percent !== null && item.percent < 100).sort((a, b) => a.percent - b.percent)
    },

    // Три лучших по выполнению плана
    strong() {
      return this.items.filter((item) => item.percent !== null && item.percent >= 100).slice(0, 3)
    },

    // Общая оценка по доле выполненных планов
    verdict() {
      if (!this.items.length) return 'warn'
      const share = this.metCount / this.items.length
      if (share >= 0.8) return 'good'
      return share >= 0.5 ? 'warn' : 'bad'
    },

    ringLength() {
      if (!this.ready || !this.items.length) return 0
      return (this.metCount / this.items.length) * CIRCLE
    },
  },

  mounted() {
    this.readyTimer = setTimeout(() => (this.ready = true), 350)
  },

  beforeUnmount() {
    clearTimeout(this.readyTimer)
  },

  methods: {
    number(value, digits) {
      if (typeof value !== 'number') return '—'
      return new Intl.NumberFormat(this.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value)
    },

    percent(value) {
      return `${this.number(value, 1)}%`
    },

    planWidth(percent) {
      return this.ready && percent !== null ? (Math.min(percent, PLAN_MAX) / PLAN_MAX) * 100 : 0
    },

    // Рост рисуется от центра вправо, падение влево; половина полосы — YOY_MAX процентов
    yoyWidth(delta) {
      return this.ready ? (Math.min(Math.abs(delta), YOY_MAX) / YOY_MAX) * 50 : 0
    },
  },
}
</script>

