import { defineStore } from 'pinia'
import { API } from '@/configurations'
import { fetchCompany } from '@/services/company'

let retryTimer = null

export const useCompanyStore = defineStore('company', {
  state: () => ({
    rows: [],
    loading: false,
    // Данных ещё нет, а последняя попытка загрузки не удалась
    failed: false,
  }),

  getters: {
    loaded: (state) => state.rows.length > 0,

    // Самый свежий период: последняя строка таблицы
    latest: (state) => (state.rows.length ? state.rows[state.rows.length - 1] : null),
  },

  actions: {
    // Пока данных нет, запрос повторяется каждые API.RETRY_MS, а интерфейс показывает индикатор загрузки
    async load() {
      if (this.loading) return
      clearTimeout(retryTimer)
      this.loading = true
      try {
        this.rows = await fetchCompany()
        this.failed = false
      } catch {
        if (!this.loaded) {
          this.failed = true
          retryTimer = setTimeout(() => this.load(), API.RETRY_MS)
        }
      } finally {
        this.loading = false
      }
    },

    cancelRetry() {
      clearTimeout(retryTimer)
    },
  },
})
