<template>
  <section class="crd" :class="{ 'crd--dense': dense }" :aria-label="$t('credit.title')">
    <panel-head :icon="mdiCreditCardOutline" :title="$t('credit.title')" :period="period" />

    <ul class="crd__legend">
      <li><span class="crd__swatch crd__swatch--fact"></span>{{ $t('credit.factShare') }}</li>
      <li><span class="crd__swatch crd__swatch--plan"></span>{{ $t('credit.planShare') }}</li>
    </ul>

    <ul class="crd__rows">
      <li v-for="(item, index) in items" :key="item.manager.id" class="crd__row" :style="{ '--mc': item.rgb, '--i': index }">
        <span class="crd__name">
          <i class="crd__dot" aria-hidden="true"></i>
          {{ item.manager.name }}
        </span>

        <div class="crd__body">
          <div class="crd__plot">
            <span v-if="item.plan !== null" class="crd__plan-label" :style="{ left: `${pos(item.plan)}%` }">{{ number(item.plan, 1) }}%</span>

            <div class="crd__track">
              <span class="crd__bar" :style="{ width: `${pos(item.fact)}%` }">
                <b>{{ number(item.fact, 1) }}%</b>
              </span>
              <span v-if="item.plan !== null" class="crd__plan" :style="{ left: `${pos(item.plan)}%` }" aria-hidden="true"></span>
            </div>
          </div>

          <div class="crd__axis" aria-hidden="true">
            <span>0%</span>
            <span>{{ top }}%</span>
          </div>

          <b v-if="item.percent !== null" class="crd__status" :class="`crd__status--${item.state}`">
            <i aria-hidden="true">{{ item.percent >= 100 ? '▲' : '▼' }}</i>
            {{ number(item.percent, 1) }}% {{ $t('conversion.ofPlan') }}
          </b>
        </div>

        <div class="crd__sum">
          <b>{{ money(item.sum) }}</b>
          <small>{{ $t('credit.sumLabel') }}</small>
        </div>
      </li>
    </ul>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiCreditCardOutline } from '@mdi/js'
import PanelHead from '@/components/PanelHead.vue'
import { useScopeStore } from '@/stores/scope'
import { DENSE_FROM, completion, statusOf } from '@/utils/kpi'
import { entryRgb } from '@/utils/color'

export default {
  name: 'CreditByManagers',

  components: { PanelHead },

  data() {
    return {
      mdiCreditCardOutline,
      // Полосы растут от нуля после появления блока
      ready: false,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['current', 'kind']),
    ...mapState(useScopeStore, ['totals']),

    locale() {
      return this.$i18n.locale
    },

    // Много строк (магазины): строки компактные
    dense() {
      return this.totals.length > DENSE_FROM
    },

    period() {
      return this.current ? this.current.time : ''
    },

    // Менеджеры от большей доли кредита к меньшей
    items() {
      const list = this.totals.map(({ manager, row }) => {
        const pick = (field) => (row && typeof row[field] === 'number' ? row[field] : null)
        const fact = pick('credit_f')
        const plan = pick('credit_p')
        const percent = completion(fact, plan)
        return { manager, rgb: entryRgb(this.kind, manager, statusOf(percent)), fact, plan, sum: pick('credit_sum'), percent, state: statusOf(percent) }
      })
      return list.sort((a, b) => (b.fact === null ? -1 : b.fact) - (a.fact === null ? -1 : a.fact))
    },

    // Верх шкалы в процентах: самое большое значение, округлённое вверх до 5
    top() {
      const values = this.items.flatMap((item) => [item.fact, item.plan]).filter((value) => typeof value === 'number')
      return Math.max(5, Math.ceil((Math.max(0, ...values) * 1.1) / 5) * 5)
    },
  },

  mounted() {
    this.readyTimer = setTimeout(() => (this.ready = true), 350)
  },

  beforeUnmount() {
    clearTimeout(this.readyTimer)
  },

  methods: {
    number(value, digits) {
      if (typeof value !== 'number') return '—'
      return new Intl.NumberFormat(this.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value)
    },

    money(value) {
      if (typeof value !== 'number') return '—'
      return `${this.number(value / 1e6, 2)} ${this.$t('kpi.million')}`
    },

    pos(value) {
      return this.ready && typeof value === 'number' ? Math.min(100, (value / this.top) * 100) : 0
    },
  },
}
</script>

