import { createRouter, createWebHistory } from 'vue-router'
import { MANAGERS, managerPermission, PERMISSIONS } from '@/configurations'
import { useAccessStore } from '@/stores/access'
import DashboardLayout from '@/layouts/DashboardLayout.vue'
import HomeView from '@/views/HomeView.vue'

// meta.public — страница доступна без входа.
// meta.title — ключ перевода заголовка страницы в шапке
// meta.permission — страница доступна только с этим правом: { permission: PERMISSIONS.<ПРАВО> }
// Страница менеджера /manager/:id проверяется правом managerPermission(id): оно вычисляется из адреса, поэтому новый
// менеджер из MANAGERS получает свою страницу без правок здесь.
const routes = [
  {
    path: '/login',
    name: 'login',
    component: () => import('@/views/LoginView.vue'),
    meta: { public: true },
  },
  {
    // Все закрытые страницы живут внутри общего макета: шапка, сайдбар, подвал
    path: '/',
    component: DashboardLayout,
    children: [
      {
        path: '',
        name: 'home',
        component: HomeView,
        meta: { title: 'home.title', permission: PERMISSIONS.DASHBOARD_VIEW },
      },
      {
        // Страница менеджера: те же блоки, что на главной, но по данным менеджера и его магазинов
        path: 'manager/:id',
        name: 'manager',
        component: HomeView,
      },
      {
        path: 'forbidden',
        name: 'forbidden',
        component: () => import('@/views/ForbiddenView.vue'),
        meta: { title: 'forbidden.title' },
      },
    ],
  },
  {
    path: '/:pathMatch(.*)*',
    redirect: '/',
  },
]

const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes,
})

// Право на страницу: явное из meta или, для страницы менеджера, право на этого менеджера.
// Неизвестный менеджер (нет в MANAGERS) — страницы не существует.
function permissionOf(to) {
  if (to.name === 'manager') {
    return MANAGERS.some((manager) => manager.id === to.params.id) ? managerPermission(to.params.id) : null
  }
  return to.meta.permission
}

router.beforeEach(async (to) => {
  const access = useAccessStore()
  // Сверка с таблицей идёт в фоне; если вход отзовут, App.vue вернёт на страницу входа.
  // Закрытые страницы ждут сверки: роль в браузере можно подменить, роль из таблицы — нет.
  const check = access.restoreSession()
  if (to.meta.permission || to.name === 'manager') await check

  if (to.meta.public) {
    return to.name === 'login' && access.isAuthenticated ? access.homeRoute : true
  }

  if (!access.isAuthenticated) {
    return { name: 'login', query: to.fullPath === '/' ? {} : { redirect: to.fullPath } }
  }

  // Несуществующий менеджер и страница без права ведут на «домашнюю» страницу пользователя
  if (to.name === 'manager' && !MANAGERS.some((manager) => manager.id === to.params.id)) return access.homeRoute
  // Страница «Нет доступа» без права: в неё ведёт homeRoute тех, кому больше некуда идти
  return access.can(permissionOf(to)) ? true : access.homeRoute
})

export default router
