<template>
  <div class="divider" :class="{ 'divider--visible': visible }" role="separator">
    <span class="divider__line divider__line--left"></span>

    <span class="divider__mark" aria-hidden="true">
      <i class="divider__ring"></i>
      <i class="divider__ring divider__ring--late"></i>
      <i class="divider__dot"></i>
    </span>

    <span v-if="title" class="divider__title">{{ title }}</span>

    <span class="divider__line divider__line--right"></span>
  </div>
</template>

<script>
export default {
  name: 'SectionDivider',

  props: {
    // Необязательный заголовок следующего раздела рядом с меткой
    title: {
      type: String,
      default: '',
    },
  },

  data() {
    return {
      // Линии раскрываются от центра, когда разделитель попадает в поле зрения
      visible: false,
    }
  },

  mounted() {
    if ('IntersectionObserver' in window) {
      this.observer = new IntersectionObserver(
        ([entry]) => {
          if (!entry.isIntersecting) return
          this.visible = true
          this.observer.disconnect()
        },
        { threshold: 0.6 },
      )
      this.observer.observe(this.$el)
    }
    // Если наблюдатель не сработал (например, вкладка в фоне), всё равно показываем
    this.fallback = setTimeout(() => (this.visible = true), 1500)
  },

  beforeUnmount() {
    clearTimeout(this.fallback)
    if (this.observer) this.observer.disconnect()
  },
}
</script>

<style lang="scss" scoped>
