    }

    // Жёлтый блик бежит от края к метке и обратно
    &::after {
      content: '';
      position: absolute;
      inset: 0;
      width: 35%;
      background: linear-gradient(90deg, transparent, rgb(var(--v-theme-brand-yellow)), transparent);
