        background: linear-gradient(270deg, rgba(var(--v-theme-on-surface), 0), rgba(var(--v-theme-on-surface), 0.22));
      }
    }
  }

  &--visible &__line {
    transform: scaleX(1);
  }

  &--visible &__line--left::after {
    opacity: 1;
    animation: divider-run-left 4.8s ease-in-out 1.4s infinite;
  }

  &--visible &__line--right::after {
    opacity: 1;
    animation: divider-run-right 4.8s ease-in-out 1.4s infinite;
  }

  &__mark {
    position: relative;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    width: $mark * 2;
    height: $mark * 2;
  }

  // Жёлтый квадрат, как точка в логотипе «К.»
  &__dot {
    position: relative;
    width: $mark;
    height: $mark;
    background: rgb(var(--v-theme-brand-yellow));
    box-shadow: 0 0 16px rgba(var(--v-theme-brand-yellow), 0.75);
    transform: scale(0) rotate(-90deg);
    transition: transform 0.9s cubic-bezier(0.34, 1.56, 0.64, 1) 0.1s;
  }

  &--visible &__dot {
    transform: scale(1) rotate(45deg);
    animation: divider-spin 9s linear 1.2s infinite;
  }

  // Расходящиеся кольца вокруг метки
  &__ring {
    position: absolute;
    inset: 0;
    border: 2px solid rgb(var(--v-theme-brand-yellow));
    border-radius: 4px;
    opacity: 0;
    transform: rotate(45deg) scale(0.5);

    &--late {
      animation-delay: 1.2s !important;
    }
  }

  &--visible &__ring {
    animation: divider-ring 2.6s ease-out 1s infinite;
  }

  &__title {
    flex: none;
    color: rgba(var(--v-theme-on-surface), 0.6);
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    opacity: 0;
    transform: translateY(6px);
    transition: opacity 0.6s ease 0.5s, transform 0.6s $ease-out-expo 0.5s;
  }

  &--visible &__title {
    opacity: 1;
