<template>
  <transition name="loader">
    <div v-if="visible" class="loader" :class="{ 'loader--dark': isDark }" role="status" aria-live="polite">
      <div class="loader__field" aria-hidden="true">
        <span class="loader__pill loader__pill--a"></span>
        <span class="loader__pill loader__pill--b"></span>
        <span class="loader__pill loader__pill--c"></span>
      </div>

      <div class="loader__card">
        <div class="loader__hero">
          <svg viewBox="0 0 100 100" class="loader__ring" aria-hidden="true">
            <circle class="loader__track" cx="50" cy="50" r="46" />
            <circle
              class="loader__arc"
              cx="50"
              cy="50"
              r="46"
              :stroke-dasharray="circumference"
              :stroke-dashoffset="offset"
            />
          </svg>
          <img :src="logo" :alt="appName" class="loader__logo" width="72" height="72" />
        </div>

        <h2 class="loader__title">{{ $t('loader.title') }}</h2>
        <p class="loader__subtitle">{{ $t('loader.progress', { done: readyCount, total: list.length }) }}</p>

        <div class="loader__bar" aria-hidden="true">
          <span class="loader__fill" :style="{ width: `${progress * 100}%` }"></span>
        </div>

        <section v-for="group in groups" :key="group.id" class="loader__group">
          <h3 class="loader__caption">{{ $t(`loader.groups.${group.id}`) }}</h3>

          <ul class="loader__list">
            <li v-for="(source, index) in group.items" :key="source.id" class="loader__item" :class="`loader__item--${source.status}`" :style="{ '--i': index }">
              <span class="loader__state" aria-hidden="true">
                <v-progress-circular v-if="source.status === 'loading'" indeterminate size="18" width="2" />
                <v-icon v-else-if="source.status === 'ready'" :icon="mdiCheckCircle" size="20" />
                <v-icon v-else :icon="mdiAlertCircle" size="20" />
              </span>

              <span class="loader__name">
                <i v-if="source.color" class="loader__dot" :style="{ background: source.color }"></i>
                {{ source.titleKey ? $t(source.titleKey) : source.title }}
              </span>

              <span class="loader__status">{{ $t(`loader.status.${source.status}`) }}</span>
            </li>
          </ul>
        </section>

        <transition name="loader-problem">
          <p v-if="hasFailed" class="loader__problem">{{ $t('loader.problem') }}</p>
        </transition>
      </div>
    </div>
  </transition>
</template>

<script>
import { mapActions, mapState } from 'pinia'
import { mdiAlertCircle, mdiCheckCircle } from '@mdi/js'
import logo from '@/assets/logo.png'
import { APP } from '@/configurations'
import { useSettingsStore } from '@/stores/settings'
import { useSourcesStore } from '@/stores/sources'

const RADIUS = 46
// Короткая пауза, чтобы экран не мигал, если данные пришли мгновенно
const MIN_VISIBLE_MS = 1300

export default {
  name: 'LoadingScreen',

  data() {
    return {
      logo,
      mdiAlertCircle,
      mdiCheckCircle,
      appName: APP.NAME,
      circumference: 2 * Math.PI * RADIUS,
      minElapsed: false,
    }
  },

  computed: {
    ...mapState(useSourcesStore, ['list', 'readyCount', 'progress', 'allReady', 'hasFailed', 'visible']),
    ...mapState(useSettingsStore, ['isDark']),

    offset() {
      return this.circumference * (1 - this.progress)
    },

    // Источники по группам в порядке списка
    groups() {
      const groups = []
      for (const source of this.list) {
        let group = groups.find((item) => item.id === source.group)
        if (!group) {
          group = { id: source.group, items: [] }
          groups.push(group)
        }
        group.items.push(source)
      }
      return groups
    },

    // Всё загружено и экран показан достаточно долго
    canClose() {
      return this.allReady && this.minElapsed
    },
  },

  watch: {
    canClose(value) {
      if (value) this.finish()
    },

    // Пока экран загрузки закрывает страницу, сама страница под ним не прокручивается
    visible: {
      immediate: true,
      handler(value) {
        document.documentElement.classList.toggle('loader-lock', value)
      },
    },
  },

  mounted() {
    this.minTimer = setTimeout(() => (this.minElapsed = true), MIN_VISIBLE_MS)
  },

  beforeUnmount() {
    clearTimeout(this.minTimer)
    document.documentElement.classList.remove('loader-lock')
  },

  methods: {
    ...mapActions(useSourcesStore, ['finish']),
  },
}
</script>

