<template>
  <v-menu location="bottom end" :offset="10" :close-on-content-click="false" transition="scale-transition">
    <template #activator="{ props, isActive }">
      <v-btn
        v-bind="props"
        class="weather__chip"
        :class="[night ? 'weather__chip--night' : 'weather__chip--day', { 'weather__chip--open': isActive }]"
        :aria-label="$t('weather.title')"
        variant="flat"
        rounded="pill"
      >
        <transition name="weather-swap" mode="out-in">
          <img v-if="data" :key="data.icon" :src="data.icon" alt="" class="weather__icon" width="30" height="30" />
          <v-progress-circular v-else indeterminate size="18" width="2" class="weather__icon weather__icon--wait" />
        </transition>
        <span v-if="data" class="weather__temp">{{ degrees(data.temp) }}</span>
        <span class="weather__city">{{ cityTitle }}</span>
        <v-icon :icon="mdiChevronDown" size="18" class="weather__arrow" />
      </v-btn>
    </template>

    <v-card class="weather__card" rounded="xl" elevation="8" width="340">
      <header class="weather__head" :class="night ? 'weather__head--night' : 'weather__head--day'">
        <span class="weather__glow" aria-hidden="true"></span>

        <template v-if="data">
          <img :key="data.iconLarge" :src="data.iconLarge" :alt="data.condition" class="weather__hero" width="88" height="88" />
          <div class="weather__now">
            <span class="weather__big">{{ degrees(data.temp) }}<small>C</small></span>
            <span class="weather__condition">{{ data.condition }}</span>
          </div>
        </template>
        <div v-else class="weather__wait">
          <v-progress-circular indeterminate size="28" width="3" />
        </div>
      </header>

      <div class="weather__pick">
        <v-select
          :model-value="city"
          :items="cities"
          item-title="title"
          item-value="id"
          :label="$t('weather.city')"
          :prepend-inner-icon="mdiMapMarkerOutline"
          variant="solo-filled"
          density="comfortable"
          rounded="lg"
          flat
          hide-details
          @update:model-value="pickCity"
        />
      </div>

      <ul v-if="data" class="weather__grid">
        <li v-for="(tile, index) in tiles" :key="tile.key" class="weather__tile" :style="{ '--i': index }">
          <v-icon
            :icon="tile.icon"
            size="20"
            class="weather__tile-icon"
            :style="tile.rotate === undefined ? null : { transform: `rotate(${tile.rotate}deg)` }"
          />
          <span class="weather__tile-text">
            <small>{{ $t(`weather.${tile.key}`) }}</small>
            <strong>{{ tile.value }}</strong>
          </span>
        </li>
      </ul>

      <footer v-if="data" class="weather__foot">
        <span>{{ $t('weather.updated', { time: data.updated }) }}</span>
        <a href="https://www.weatherapi.com/" target="_blank" rel="noopener noreferrer">WeatherAPI.com</a>
      </footer>
    </v-card>
  </v-menu>
</template>

<script>
import { mapActions, mapState } from 'pinia'
import {
  mdiChevronDown,
  mdiEye,
  mdiGauge,
  mdiMapMarkerOutline,
  mdiNavigation,
  mdiThermometer,
  mdiWaterPercent,
  mdiWhiteBalanceSunny,
} from '@mdi/js'
import { WEATHER } from '@/configurations'
import { useSettingsStore } from '@/stores/settings'
import { useWeatherStore } from '@/stores/weather'

export default {
  name: 'HeaderWeather',

  data() {
    return {
      mdiChevronDown,
      mdiMapMarkerOutline,
    }
  },

  computed: {
    ...mapState(useWeatherStore, ['city', 'data']),
    ...mapState(useSettingsStore, ['locale']),

    // Ночью карточка и кнопка становятся фиолетовыми
    night() {
      return this.data ? !this.data.isDay : false
    },

    cities() {
      return WEATHER.CITIES.map(({ id }) => ({ id, title: this.$t(`cities.${id}`) }))
    },

    cityTitle() {
      return this.$t(`cities.${this.city}`)
    },

    tiles() {
      const d = this.data
      return [
        { key: 'feelsLike', icon: mdiThermometer, value: `${this.degrees(d.feelsLike)}C` },
        { key: 'humidity', icon: mdiWaterPercent, value: `${d.humidity}%` },
        {
          key: 'wind',
          icon: mdiNavigation,
          // Стрелка показывает, куда дует ветер: угол в данных указывает, откуда
          rotate: d.windDegree + 180,
          value: `${this.number(d.windMs, 1)} ${this.$t('weather.ms')}`,
        },
        { key: 'pressure', icon: mdiGauge, value: `${Math.round(d.pressureMmHg)} ${this.$t('weather.mmhg')}` },
        { key: 'visibility', icon: mdiEye, value: `${this.number(d.visibilityKm, 0)} ${this.$t('weather.km')}` },
        { key: 'uv', icon: mdiWhiteBalanceSunny, value: this.number(d.uv, 0) },
      ]
    },
  },

  watch: {
    // Описание погоды приходит на языке интерфейса
    locale() {
      this.reload()
    },
  },

  mounted() {
    this.reload()
    this.timer = setInterval(this.reload, WEATHER.REFRESH_MS)
  },

  beforeUnmount() {
    clearInterval(this.timer)
    this.cancelRetry()
  },

  methods: {
    ...mapActions(useWeatherStore, ['load', 'setCity', 'cancelRetry']),

    reload() {
      return this.load(this.locale)
    },

    pickCity(id) {
      return this.setCity(id, this.locale)
    },

    degrees(value) {
      return `${Math.round(value)}°`
    },

    number(value, digits) {
      return new Intl.NumberFormat(this.locale, {
        minimumFractionDigits: digits,
        maximumFractionDigits: digits,
      }).format(value)
    },
  },
}
</script>

