<template>
  <v-app-bar flat :height="72" class="header">
    <v-btn
      :icon="desktop && !rail ? mdiMenuOpen : mdiMenu"
      :aria-label="menuLabel"
      class="header__toggle"
      variant="text"
      @click="$emit('toggle')"
    />

    <transition name="header-title" mode="out-in">
      <h1 :key="title" class="header__title">{{ title }}</h1>
    </transition>

    <v-spacer />

    <header-date class="header__date" />

    <v-spacer />

    <!-- Уже экрана не помещаются, поэтому не показываем и не загружаем -->
    <template v-if="showInfo">
      <header-weather />

      <header-rates />
    </template>

    <header-language />

    <header-theme />
  </v-app-bar>
</template>

<script>
import { mdiMenu, mdiMenuOpen } from '@mdi/js'
import HeaderDate from '@/components/HeaderDate.vue'
import HeaderLanguage from '@/components/HeaderLanguage.vue'
import HeaderRates from '@/components/HeaderRates.vue'
import HeaderTheme from '@/components/HeaderTheme.vue'
import HeaderWeather from '@/components/HeaderWeather.vue'
import { MANAGERS, UI } from '@/configurations'

export default {
  name: 'AppHeader',

  components: { HeaderDate, HeaderLanguage, HeaderRates, HeaderTheme, HeaderWeather },

  props: {
    // Сайдбар в узком режиме (компьютер)
    rail: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['toggle'],

  data() {
    return {
      mdiMenu,
      mdiMenuOpen,
    }
  },

  computed: {
    desktop() {
      return this.$vuetify.display.mdAndUp
    },

    // Погода и курс валют показываются только на экранах от UI.INFO_MIN_WIDTH
    showInfo() {
      return this.$vuetify.display.width >= UI.INFO_MIN_WIDTH
    },

    title() {
      if (this.$route.name === 'manager') {
        const manager = MANAGERS.find((item) => item.id === this.$route.params.id)
        return manager ? manager.name : ''
      }
      const key = this.$route.meta.title
      return key ? this.$t(key) : ''
    },

    menuLabel() {
      if (!this.desktop) return this.$t('common.menu')
      return this.$t(this.rail ? 'common.expand' : 'common.collapse')
    },
  },
}
</script>

<style lang="scss" scoped>
.header {
  border-bottom: 1px solid rgba(var(--v-theme-on-surface), 0.08);
  background: rgba(var(--v-theme-surface), 0.85) !important;
  backdrop-filter: blur(12px);
  animation: header-in 0.6s $ease-out-expo both;

  &__title {
    margin-left: $spacer * 2;
    font-size: 1.35rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    white-space: nowrap;
  }

  // На телефоне блок с датой и шкалой не помещается
  @include phone {
    &__date {
      display: none;
    }
  }

  // Места мало: убираем заголовок, шапка и так показывает дату
  @media (min-width: 600px) and (max-width: 1099px) {
    &__title {
      display: none;
    }
  }
}

.header-title-enter-active,
.header-title-leave-active {
  transition: opacity 0.18s ease, transform 0.25s $ease-out-expo;
}

.header-title-enter-from {
  opacity: 0;
  transform: translateY(8px);
}

.header-title-leave-to {
  opacity: 0;
  transform: translateY(-8px);
}

@keyframes header-in {
  from {
    opacity: 0;
    transform: translateY(-16px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .header {
    animation: none;
  }

  .header-title-enter-active,
  .header-title-leave-active {
    transition: none;
  }
}
</style>
