import { defineStore } from 'pinia'
import {
  ALL_PERMISSIONS,
  APP,
  AUTH,
  MANAGERS,
  managerPermission,
  PERMISSIONS,
  ROLE_PERMISSIONS,
  ROLES,
  STORAGE_KEYS,
} from '@/configurations'
import * as authApi from '@/services/auth'
import { deepClone } from '@/utils/clone'
import { readStorage, writeStorage } from '@/utils/storage'

// Максимальная задержка setTimeout (~24,8 дня), больше браузер не поддерживает
const MAX_TIMEOUT = 2 ** 31 - 1

let expiryTimer = null
let restorePromise = null
let watching = false

function isExpired(session) {
  return !session || !session.user || !session.expiresAt || session.expiresAt <= Date.now() || session.version !== APP.VERSION
}

export const useAccessStore = defineStore('access', {
  // Роли и права берутся из configurations.js, дальше живут реактивно в хранилище
  state: () => ({
    roles: { ...ROLES },
    permissions: { ...PERMISSIONS },
    rolePermissions: deepClone(ROLE_PERMISSIONS),
    // В сессии хранятся только логин, роль и срок действия, пароль не сохраняется
    session: readStorage(STORAGE_KEYS.SESSION),
    sessionChecked: false,
  }),

  getters: {
    currentUser(state) {
      return isExpired(state.session) ? null : state.session.user
    },

    currentRole() {
      return this.currentUser ? this.currentUser.role : null
    },

    isAuthenticated() {
      return this.currentUser !== null
    },

    currentPermissions() {
      return this.currentRole ? this.rolePermissions[this.currentRole] || [] : []
    },

    // Есть ли доступ к главной странице (общие показатели компании)
    canViewCompany() {
      return this.can(PERMISSIONS.DASHBOARD_VIEW)
    },

    // Менеджеры, страницы которых доступны пользователю, в порядке MANAGERS
    allowedManagers() {
      return MANAGERS.filter((manager) => this.can(managerPermission(manager.id)))
    },

    // Если пользователь сам менеджер (его роль совпадает с id из MANAGERS), это его запись; иначе null
    ownManager() {
      return this.currentRole ? MANAGERS.find((manager) => manager.id === this.currentRole) || null : null
    },

    // Куда вести пользователя после входа и при попытке открыть закрытую страницу: главная, иначе первая доступная страница РМ,
    // иначе страница «Нет доступа»
    homeRoute() {
      if (this.canViewCompany) return { name: 'home' }
      const [first] = this.allowedManagers
      return first ? { name: 'manager', params: { id: first.id } } : { name: 'forbidden' }
    },

    // Использование: access.can(PERMISSIONS.REPORTS_EDIT)
    can() {
      return (permission) => {
        if (!permission) return true
        const granted = this.currentPermissions
        return granted.includes(ALL_PERMISSIONS) || granted.includes(permission)
      }
    },
  },

  actions: {
    setSession(session) {
      this.session = session
      writeStorage(STORAGE_KEYS.SESSION, session)
      this.scheduleExpiry()
    },

    // Выход ровно в момент окончания сессии, даже если вкладка всё это время открыта
    scheduleExpiry() {
      clearTimeout(expiryTimer)
      if (!this.session) return
      const left = this.session.expiresAt - Date.now()
      if (left <= 0) {
        this.logout()
        return
      }
      expiryTimer = setTimeout(() => this.scheduleExpiry(), Math.min(left, MAX_TIMEOUT))
    },

    // Вызывается один раз при запуске: таймер окончания сессии и синхронизация входа/выхода между вкладками
    watchSession() {
      if (watching) return
      watching = true
      this.scheduleExpiry()
      window.addEventListener('storage', (event) => {
        if (event.key !== STORAGE_KEYS.SESSION && event.key !== null) return
        this.session = readStorage(STORAGE_KEYS.SESSION)
        this.scheduleExpiry()
      })
    },

    async login(login, password) {
      const user = await authApi.login(login, password)
      this.setSession({ user, expiresAt: Date.now() + AUTH.SESSION_HOURS * 60 * 60 * 1000, version: APP.VERSION })
      // Свежий вход уже сверен с таблицей, повторная проверка не нужна
      restorePromise = Promise.resolve()
      this.sessionChecked = true
    },

    // Один раз за запуск сверяет сохранённый вход с таблицей: роль могла измениться, пользователя могли удалить.
    // Срок сессии при этом не продлевается. Повторные вызовы ждут ту же проверку.
    restoreSession() {
      if (!restorePromise) restorePromise = this.checkSession()
      return restorePromise
    },

    async checkSession() {
      if (isExpired(this.session)) {
        if (this.session) this.setSession(null)
        this.sessionChecked = true
        return
      }

      try {
        const { login } = this.session.user
        const user = await authApi.refreshUser(login)
        // Пока шёл запрос, пользователь мог выйти или войти под другим логином
        if (this.session && this.session.user.login === login) {
          this.setSession(user ? { ...this.session, user } : null)
        }
      } catch {
        // Таблица недоступна: оставляем сохранённый вход, проверим при следующем запуске
      } finally {
        this.sessionChecked = true
      }
    },

    logout() {
      this.setSession(null)
    },

    setRolePermissions(role, permissions) {
      this.rolePermissions[role] = [...new Set(permissions)]
    },

    grantPermission(role, permission) {
      const current = this.rolePermissions[role] || []
      this.setRolePermissions(role, [...current, permission])
    },

    revokePermission(role, permission) {
      const current = this.rolePermissions[role] || []
      this.setRolePermissions(role, current.filter((item) => item !== permission))
    },
  },
})
