import { defineStore } from 'pinia'
import { useAccessStore } from '@/stores/access'
import { useCompanyStore } from '@/stores/company'
import { useManagersStore } from '@/stores/managers'

// loading — ждём ответ, ready — данные есть, error — данных нет, пробуем снова
function statusOf(ready, failed) {
  if (ready) return 'ready'
  return failed ? 'error' : 'loading'
}

// Учёт основных источников данных, без которых дашборд не открывается: компания (если у пользователя есть доступ к главной)
// и каждый менеджер, страница которого ему доступна. Менеджер, например, загружает только свою таблицу.
// Общий прелоадер показывает их состояние, пока все они не ответят. Источник, который не отвечает или отвечает с ошибкой,
// перезапрашивается, пока не даст ответ; пропустить его нельзя. Курс валют и погода второстепенные: они не входят
// в этот список, каждый из них загружается сам и не задерживает открытие дашборда.
export const useSourcesStore = defineStore('sources', {
  state: () => ({
    started: false,
    // Все основные данные пришли, прелоадер закрыт
    finished: false,
  }),

  getters: {
    list() {
      const company = useCompanyStore()
      const managers = useManagersStore()
      const access = useAccessStore()
      const allowed = access.allowedManagers.map((manager) => manager.id)

      const list = []
      if (access.canViewCompany) {
        list.push({ id: 'company', group: 'main', titleKey: 'loader.company', status: statusOf(company.loaded, company.failed) })
      }
      for (const manager of managers.list.filter((item) => allowed.includes(item.id))) {
        list.push({
          id: `manager:${manager.id}`,
          group: 'managers',
          title: manager.name,
          color: manager.color,
          status: manager.status === 'idle' ? 'loading' : manager.status,
        })
      }
      return list
    },

    readyCount() {
      return this.list.filter((source) => source.status === 'ready').length
    },

    progress() {
      return this.list.length ? this.readyCount / this.list.length : 1
    },

    allReady() {
      // Пустой список (у пользователя нет ни одного источника) тоже считается загруженным, иначе прелоадер не закрылся бы
      return this.readyCount === this.list.length
    },

    hasFailed() {
      return this.list.some((source) => source.status === 'error')
    },

    // Прелоадер виден с момента входа, пока все основные данные не пришли
    visible: (state) => state.started && !state.finished,
  },

  actions: {
    // Запускает загрузку основных источников. Повторный вызов ничего не делает: таблицы не перечитываются
    start() {
      if (this.started) return
      this.started = true
      this.finished = false
      const access = useAccessStore()
      if (access.canViewCompany) useCompanyStore().load()
      useManagersStore().loadAll(access.allowedManagers.map((manager) => manager.id))
    },

    // Выход из аккаунта: останавливаем повторы, при следующем входе данные загрузятся заново
    stop() {
      useCompanyStore().cancelRetry()
      useManagersStore().cancelRetry()
      this.started = false
      this.finished = false
    },

    finish() {
      this.finished = true
    },
  },
})
