// Все права в системе. Страницы и кнопки проверяют именно их, а не роли.
export const PERMISSIONS = {
  DASHBOARD_VIEW: 'dashboard.view',
  REPORTS_VIEW: 'reports.view',
  REPORTS_EDIT: 'reports.edit',
  USERS_VIEW: 'users.view',
  USERS_MANAGE: 'users.manage',
  SETTINGS_MANAGE: 'settings.manage',
}

// Означает «все права»
export const ALL_PERMISSIONS = '*'

// Право на страницу менеджера: managerPermission('stadnik') → 'manager.stadnik'.
// Страницы менеджеров будут проверять именно его.
export const managerPermission = (id) => `manager.${id}`

// Роли совпадают со значениями столбца RoleStatus в таблице пользователей.
// Роль менеджера — его id из MANAGERS (создаётся автоматически). Остальные пользователи добавляются строкой в таблицу.
export const ROLES = {
  SUPER: 'super',
  CEO: 'ceo',
  ANALYST: 'analyst',
  ...Object.fromEntries(MANAGERS.map((manager) => [manager.id.toUpperCase(), manager.id])),
}

// Страницы всех менеджеров одним списком прав: пригодится, когда нужно дать роли доступ ко всем РМ
const ALL_MANAGER_PAGES = MANAGERS.map((manager) => managerPermission(manager.id))

// Права каждой роли. Чтобы изменить доступ роли, достаточно поправить её список (и поменять APP.VERSION,
// чтобы у уже вошедших пользователей права обновились).
// Роль из таблицы, которой здесь нет, может войти, но не получает ни одной страницы.
//  analyst — безусловно всё
//  ceo     — ровно то, что перечислено: главная и страницы РМ. Уберите или добавьте право в список, чтобы изменить доступ
//  super   — главная и страницы всех РМ
//  менеджер — только своя страница (managerPermission(id)), больше никуда
export const ROLE_PERMISSIONS = {
  [ROLES.ANALYST]: [ALL_PERMISSIONS],
  [ROLES.CEO]: [PERMISSIONS.DASHBOARD_VIEW, ...ALL_MANAGER_PAGES],
  [ROLES.SUPER]: [PERMISSIONS.DASHBOARD_VIEW, ...ALL_MANAGER_PAGES],
  ...Object.fromEntries(MANAGERS.map((manager) => [manager.id, [managerPermission(manager.id)]])),
}
