<template>
  <section class="chk" :class="{ 'chk--dense': dense }" :aria-label="heading">
    <panel-head :icon="mdiReceiptTextOutline" :title="heading" :period="period" />

    <ul class="chk__legend">
      <li><span class="chk__swatch chk__swatch--fact"></span>{{ $t('kpi.fact') }}</li>
      <li><span class="chk__swatch chk__swatch--plan"></span>{{ $t('kpi.plan') }}</li>
      <li><span class="chk__swatch chk__swatch--past"></span>{{ $t('traffic.pastShort') }}</li>
      <li class="chk__legend-coin">{{ $t('check.coin', { n: number(step) }) }}</li>
    </ul>

    <!-- У каждого менеджера три строки из монет на общей шкале: факт (цветная), план (пустая пунктирная), прошлый год (серая).
         У каждой строки слева подпись, справа точная сумма. Сравнивается длина соседних строк. -->
    <ul class="chk__list">
      <li v-for="(item, index) in items" :key="item.manager.id" class="chk__item" :style="{ '--mc': item.rgb, '--unit': `${unit}%` }">
        <div class="chk__who">
          <span class="chk__name">
            <i class="chk__dot" aria-hidden="true"></i>
            {{ item.manager.name }}
            <v-icon v-if="item.best" :icon="mdiCrown" size="16" class="chk__crown" />
          </span>
          <b class="chk__pill" :class="`chk__pill--${item.state}`">{{ item.percent === null ? '—' : `${percent(item.percent)}%` }}</b>
          <b v-if="item.delta !== null" class="chk__delta" :class="item.delta >= 0 ? 'chk__delta--good' : 'chk__delta--bad'">
            {{ item.delta >= 0 ? '▲' : '▼' }} {{ number(Math.abs(item.delta)) }}% <span class="chk__vs">{{ $t('kpi.vsPast') }}</span>
          </b>
        </div>

        <div class="chk__lines">
          <div class="chk__line">
            <span class="chk__label">{{ $t('kpi.fact') }}</span>
            <span class="chk__track">
              <span v-for="(coin, k) in item.factCoins" :key="k" class="chk__coin" :style="{ '--h': coin.h, '--dc': `${index * 120 + k * 45}ms` }" aria-hidden="true">
                <span class="chk__face"></span>
              </span>
            </span>
            <b class="chk__amount">{{ number(item.fact) }}</b>
          </div>

          <div class="chk__line">
            <span class="chk__label">{{ $t('kpi.plan') }}</span>
            <span class="chk__track">
              <span v-for="(coin, k) in item.planCoins" :key="k" class="chk__coin chk__coin--plan" :style="{ '--h': coin.h, '--dc': `${index * 120 + 120 + k * 35}ms` }" aria-hidden="true">
                <span class="chk__face"></span>
              </span>
            </span>
            <span class="chk__amount chk__amount--muted">{{ number(item.plan) }}</span>
          </div>

          <div class="chk__line">
            <span class="chk__label">{{ $t('traffic.pastShort') }}</span>
            <span class="chk__track">
              <span v-for="(coin, k) in item.pastCoins" :key="k" class="chk__coin chk__coin--past" :style="{ '--h': coin.h, '--dc': `${index * 120 + 240 + k * 35}ms` }" aria-hidden="true">
                <span class="chk__face"></span>
              </span>
            </span>
            <span class="chk__amount chk__amount--muted">{{ number(item.past) }}</span>
          </div>
        </div>
      </li>
    </ul>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiCrown, mdiReceiptTextOutline } from '@mdi/js'
import PanelHead from '@/components/PanelHead.vue'
import { useScopeStore } from '@/stores/scope'
import { DENSE_FROM, completion, growth, statusOf } from '@/utils/kpi'
import { entryRgb } from '@/utils/color'

// Сколько монет в самой длинной строке, не больше
const MAX_COINS = 11
// Подходящие «круглые» цены монеты в гривнах
const STEPS = [100, 200, 250, 500, 1000, 2000, 2500, 5000, 10000]

export default {
  name: 'CheckByManagers',

  components: { PanelHead },

  data() {
    return {
      mdiCrown,
      mdiReceiptTextOutline,
      // Ширина одной монеты в процентах длины строки: в строку влезает MAX_COINS монет с небольшим запасом
      unit: 100 / (MAX_COINS + 0.4),
    }
  },

  computed: {
    ...mapState(useScopeStore, ['current', 'kind']),
    ...mapState(useScopeStore, ['totals']),

    locale() {
      return this.$i18n.locale
    },

    // Много строк (магазины): строки компактные
    dense() {
      return this.totals.length > DENSE_FROM
    },

    heading() {
      return this.$t(this.kind === 'stores' ? 'check.titleStores' : 'check.title')
    },

    period() {
      return this.current ? this.current.time : ''
    },

    // Цена одной монеты: самая маленькая круглая, при которой все значения влезают в MAX_COINS монет
    step() {
      const values = this.totals
        .flatMap(({ row }) => (row ? [row.check_f, row.check_p, row.check_past] : []))
        .filter((value) => typeof value === 'number')
      const max = Math.max(1, ...values)
      return STEPS.find((step) => max / step <= MAX_COINS) || STEPS[STEPS.length - 1]
    },

    // Менеджеры от большего среднего чека к меньшему
    items() {
      const step = this.step
      const list = this.totals.map(({ manager, row }) => {
        const pick = (field) => (row && typeof row[field] === 'number' ? row[field] : null)
        const fact = pick('check_f')
        const plan = pick('check_p')
        const past = pick('check_past')
        const level = (value) => (value === null ? 0 : value / step)
        const percent = completion(fact, plan)
        return {
          manager,
          rgb: entryRgb(this.kind, manager, statusOf(percent)),
          fact,
          plan,
          past,
          percent,
          state: statusOf(percent),
          delta: growth(fact, past),
          factCoins: this.coinsFor(level(fact)),
          planCoins: this.coinsFor(level(plan)),
          pastCoins: this.coinsFor(level(past)),
        }
      })
      list.sort((a, b) => (b.fact === null ? -1 : b.fact) - (a.fact === null ? -1 : a.fact))
      // Корона у самого большого чека
      if (list.length && list[0].fact !== null) list[0].best = true
      return list
    },
  },

  methods: {
    number(value) {
      if (typeof value !== 'number') return '—'
      return new Intl.NumberFormat(this.locale, { maximumFractionDigits: 0 }).format(value)
    },

    percent(value) {
      return new Intl.NumberFormat(this.locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(value)
    },

    // Монеты слева направо: целые шириной 1 и неполная в конце с шириной в долях монеты
    coinsFor(level) {
      const full = Math.floor(level)
      const rest = level - full
      const coins = Array.from({ length: full }, () => ({ h: 1 }))
      if (rest >= 0.12) coins.push({ h: rest })
      return coins
    },
  },
}
</script>

