<template>
  <section class="cat" :aria-label="$t('category.title')">
    <panel-head :icon="mdiShoppingOutline" :title="$t('category.title')" :period="period" />

    <p class="cat__hint">{{ $t(tall ? 'category.hintStores' : 'category.hint') }}</p>

    <template v-if="!tall">
      <!-- На телефоне подписи строк — только значки, поэтому названия категорий даём списком -->
      <ul class="cat__legend">
        <li v-for="category in categories" :key="category.id" :style="{ '--cc': category.rgb }">
          <span class="cat__legend-icon"><v-icon :icon="category.icon" size="14" /></span>
          {{ $t(category.title) }}
        </li>
      </ul>

      <!-- Одна сетка на всю матрицу: подписи, колонка компании и пять менеджеров -->
      <div class="cat__grid">
        <span class="cat__company-bg" aria-hidden="true"></span>

        <span class="cat__corner"></span>
        <span class="cat__head cat__head--company">{{ totalLabel }}</span>
        <span v-for="entry in managers" :key="entry.manager.id" class="cat__head" :style="{ '--mc': entry.rgb }">
          <i class="cat__dot" aria-hidden="true"></i>
          {{ entry.manager.name }}
        </span>

        <template v-for="(category, row) in categories" :key="category.id">
          <span class="cat__label" :style="{ '--cc': category.rgb }">
            <span class="cat__label-icon"><v-icon :icon="category.icon" size="20" /></span>
            <span class="cat__label-text">{{ $t(category.title) }}</span>
          </span>

          <span v-for="(cell, col) in cells[row]" :key="cell.key" class="cat__cell" :class="{ 'cat__cell--company': cell.company }" :style="{ '--cc': category.rgb, '--d': `${row * 90 + col * 60}ms` }">
            <span class="cat__slot" :title="`${$t(category.title)} · ${cell.name}: ${percent(cell.value)}`">
              <span class="cat__bubble" :style="{ width: `${cell.size}%`, height: `${cell.size}%` }"></span>
              <v-icon v-if="cell.best" :icon="mdiCrown" size="14" class="cat__crown" />
            </span>
            <b class="cat__value" :class="{ 'cat__value--best': cell.best }">{{ percent(cell.value) }}</b>
          </span>
        </template>
      </div>
    </template>

    <!-- Много строк (магазины РМ): магазины идут строками, категории — колонками -->
    <div v-else class="cat__tall">
      <ul class="cat__legend">
        <li v-for="category in categories" :key="category.id" :style="{ '--cc': category.rgb }">
          <span class="cat__legend-icon"><v-icon :icon="category.icon" size="14" /></span>
          {{ $t(category.title) }}
        </li>
      </ul>

      <div class="cat__thead" aria-hidden="true">
        <span></span>
        <span v-for="category in categories" :key="category.id" class="cat__tcat" :style="{ '--cc': category.rgb }">
          <span class="cat__tcat-icon"><v-icon :icon="category.icon" size="18" /></span>
          <span class="cat__tcat-text">{{ $t(category.title) }}</span>
        </span>
      </div>

      <ul class="cat__trows">
        <li v-for="row in tallRows" :key="row.key" class="cat__trow" :class="{ 'cat__trow--total': row.total }">
          <span class="cat__tname">{{ row.name }}</span>
          <span
            v-for="(cell, colIndex) in row.cells"
            :key="colIndex"
            class="cat__tcell"
            :style="{ '--cc': categories[colIndex].rgb }"
            :title="`${row.name} · ${$t(categories[colIndex].title)}: ${percent(cell.value)}`"
          >
            <!-- Цвет ячейки: категория, насыщенность — значение относительно самого большого в колонке -->
            <b class="cat__tvalue" :class="{ 'cat__tvalue--strong': cell.alpha > 0.55, 'cat__tvalue--empty': !cell.value }" :style="{ '--a': cell.alpha }">{{ percent(cell.value) }}</b>
          </span>
        </li>
      </ul>
    </div>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiCrown, mdiShoppingOutline } from '@mdi/js'
import PanelHead from '@/components/PanelHead.vue'
import { useScopeStore } from '@/stores/scope'
import { CATEGORIES } from '@/utils/kpi'
import { hexToRgb } from '@/utils/color'

export default {
  name: 'CategoryShare',

  components: { PanelHead },

  data() {
    return {
      mdiCrown,
      mdiShoppingOutline,
      categories: CATEGORIES.map((category) => ({ ...category, rgb: hexToRgb(category.color) })),
    }
  },

  computed: {
    ...mapState(useScopeStore, ['current', 'kind']),
    ...mapState(useScopeStore, ['totals']),

    locale() {
      return this.$i18n.locale
    },

    // У страницы РМ строк много (магазины), поэтому матрица разворачивается
    tall() {
      return this.kind === 'stores'
    },

    // Подпись итога: у компании «Компанія», у РМ «Усього»
    totalLabel() {
      return this.$t(this.tall ? 'category.total' : 'category.company')
    },

    period() {
      return this.current ? this.current.time : ''
    },

    // Менеджеры в порядке конфигурации: колонки не прыгают при смене периода
    managers() {
      return this.totals.map(({ manager, row }) => ({ manager, row, rgb: hexToRgb(manager.color) }))
    },

    // Ячейки по строкам: компания и менеджеры. Размер круга считается от лучшего значения в строке
    cells() {
      return this.categories.map((category) => {
        const pick = (row) => (row && typeof row[category.field] === 'number' ? row[category.field] : null)
        const list = [
          { key: 'company', name: this.totalLabel, company: true, value: pick(this.current) },
          ...this.managers.map((entry) => ({ key: entry.manager.id, name: entry.manager.name, company: false, value: pick(entry.row) })),
        ]
        const values = list.map((cell) => cell.value).filter((value) => value !== null)
        const max = Math.max(0, ...values)
        const bestManager = Math.max(0, ...list.filter((cell) => !cell.company && cell.value !== null).map((cell) => cell.value))
        return list.map((cell) => ({
          ...cell,
          // Площадь круга пропорциональна значению, но совсем маленькие круги остаются видимыми
          size: cell.value === null || max === 0 ? 0 : 24 + 76 * Math.sqrt(cell.value / max),
          // Для тепловой карты страницы РМ: чем больше значение в колонке, тем насыщеннее цвет
          alpha: cell.value === null || !cell.value || max === 0 ? 0 : 0.14 + 0.76 * (cell.value / max),
          best: !cell.company && cell.value !== null && cell.value === bestManager && bestManager > 0,
        }))
      })
    },

    // Те же ячейки, но по строкам: первая строка — итог РМ, дальше магазины; в каждой пять ячеек по категориям.
    // Если магазин один, итог повторял бы его строку, поэтому итога нет
    tallRows() {
      const count = this.cells.length ? this.cells[0].length : 0
      const rows = Array.from({ length: count }, (_, index) => {
        const first = this.cells[0][index]
        return { key: first.key, name: first.name, total: first.company, cells: this.cells.map((row) => row[index]) }
      })
      return rows.length === 2 ? rows.filter((row) => !row.total) : rows
    },
  },

  methods: {
    percent(value) {
      if (typeof value !== 'number') return '—'
      return `${new Intl.NumberFormat(this.locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(value)}%`
    },
  },
}
</script>

