import { COMPANY } from '@/configurations'
import { gasGet } from '@/services/gas'

// Текстовые столбцы таблиц; остальные значения — числа
const TEXT_COLUMNS = ['time', 'company']

// Приводит значение поля к числу: пустая строка (например, mono_past до сентября) значит «данных нет»
function toNumber(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null
  if (typeof value === 'string' && value.trim() !== '') {
    const number = Number(value.replace(',', '.'))
    return Number.isFinite(number) ? number : null
  }
  return null
}

// Строки таблицы: текстовые столбцы остаются строкой, остальные — число или null
export function normalizeRows(list) {
  return list.map((row) => {
    const result = {}
    for (const key of Object.keys(row)) {
      result[key] = TEXT_COLUMNS.includes(key) ? String(row[key] ?? '') : toNumber(row[key])
    }
    return result
  })
}

// Строки показателей компании в порядке таблицы: сначала закрытые месяцы, затем нарастающие итоги.
export async function fetchCompany() {
  const data = await gasGet(COMPANY.URL)
  if (!data || !Array.isArray(data.info)) throw new Error('Company: неожиданный ответ')
  return normalizeRows(data.info)
}
