import { API } from '@/configurations'
import { GasError, gasGet } from './gas'

function normalizeLogin(value) {
  return String(value ?? '').trim().toLowerCase()
}

// Скрипт авторизации отдаёт весь лист Login: { stuff: [{ LoginName, PasswordEmail, RoleStatus }] }
async function fetchUsers() {
  const data = await gasGet(API.AUTH_URL)
  if (!data || !Array.isArray(data.stuff)) throw new GasError('server_error')
  return data.stuff
}

function findUser(users, login) {
  const key = normalizeLogin(login)
  return users.find((user) => normalizeLogin(user.LoginName) === key) || null
}

// Список с паролями живёт только внутри этих функций и никуда не сохраняется
export async function login(login, password) {
  const user = findUser(await fetchUsers(), login)
  if (!user || String(user.PasswordEmail ?? '').trim() !== String(password).trim()) {
    throw new GasError('invalid_credentials')
  }
  return { login: String(user.LoginName).trim(), role: String(user.RoleStatus ?? '').trim() }
}

// Возвращает актуальные логин и роль или null, если пользователя удалили из таблицы
export async function refreshUser(login) {
  const user = findUser(await fetchUsers(), login)
  return user ? { login: String(user.LoginName).trim(), role: String(user.RoleStatus ?? '').trim() } : null
}
