<template>
  <div class="orb" role="img" :aria-label="label">
    <div class="orb__scene">
      <svg viewBox="0 0 100 100" class="orb__svg" aria-hidden="true">
        <defs>
          <clipPath :id="`${uid}-clip`">
            <circle cx="50" cy="50" r="43.5" />
          </clipPath>
          <linearGradient :id="`${uid}-liquid`" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" class="orb__stop orb__stop--top" />
            <stop offset="1" class="orb__stop orb__stop--bottom" />
          </linearGradient>
          <!-- Стекло: светлее сверху слева, темнее к краю -->
          <radialGradient :id="`${uid}-glass`" cx="0.36" cy="0.28" r="0.85">
            <stop offset="0" stop-color="#fff" stop-opacity="0.5" />
            <stop offset="0.45" stop-color="#fff" stop-opacity="0" />
            <stop offset="1" class="orb__stop orb__stop--edge" />
          </radialGradient>
        </defs>

        <circle class="orb__shell" cx="50" cy="50" r="46" />

        <g :clip-path="`url(#${uid}-clip)`">
          <g class="orb__liquid" :style="{ transform: `translateY(${level}px)` }">
            <g class="orb__wave orb__wave--back"><path :d="WAVE" class="orb__back" /></g>
            <g class="orb__wave"><path :d="WAVE" :fill="`url(#${uid}-liquid)`" /></g>
            <!-- Пузырьки поднимаются, когда план перевыполнен -->
            <template v-if="over">
              <circle v-for="bubble in BUBBLES" :key="bubble.x" class="orb__bubble" :cx="bubble.x" :cy="bubble.y" :r="bubble.r" :style="{ animationDelay: bubble.delay }" />
            </template>
          </g>
          <circle cx="50" cy="50" r="43.5" :fill="`url(#${uid}-glass)`" />
        </g>

        <!-- Блики на стекле -->
        <ellipse class="orb__shine" cx="35" cy="24" rx="15" ry="7" transform="rotate(-32 35 24)" />
        <path class="orb__rim" d="M28 82 Q50 96 72 82" />
      </svg>

      <div class="orb__text" :class="{ 'orb__text--on-liquid': fraction >= 0.55 }">
        <strong>{{ text }}</strong>
        <small v-if="caption">{{ caption }}</small>
      </div>
    </div>
  </div>
</template>

<script>
// Внутренняя область шара по высоте: от 6 (верх) до 94 (низ)
const TOP = 6
const BOTTOM = 94
// Волна с периодом 50: сдвиг на 50 по оси X даёт бесшовную анимацию
const WAVE = 'M0 3 Q12.5 -3 25 3 T50 3 T75 3 T100 3 T125 3 T150 3 T175 3 T200 3 V120 H0 Z'
const BUBBLES = [
  { x: 34, y: 60, r: 3, delay: '0s' },
  { x: 55, y: 70, r: 2.2, delay: '0.7s' },
  { x: 66, y: 55, r: 3.4, delay: '1.4s' },
  { x: 46, y: 80, r: 1.8, delay: '2.1s' },
]

// Стеклянный шар выполнения плана: цветная жидкость доходит до уровня плана, на поверхности бегут волны.
// Цвет берётся из CSS-переменной --kpi родителя (RGB через запятую), наклон — из --rx и --ry карточки.
export default {
  name: 'LiquidOrb',

  props: {
    // Заполнение от 0 до 1 (уже с учётом анимации появления)
    fraction: {
      type: Number,
      default: 0,
    },
    // Текст в центре и подпись под ним
    text: {
      type: String,
      default: '',
    },
    caption: {
      type: String,
      default: '',
    },
    // Описание для скринридера
    label: {
      type: String,
      default: '',
    },
    // Уникальный суффикс id градиентов и clipPath
    uid: {
      type: String,
      required: true,
    },
    // План перевыполнен больше чем на 100 %: тогда поднимаются пузырьки
    over: {
      type: Boolean,
      default: false,
    },
  },

  data() {
    return { WAVE, BUBBLES }
  },

  computed: {
    // Уровень поверхности в координатах SVG (чем больше заполнение, тем выше)
    level() {
      const fraction = Math.min(1, Math.max(0, this.fraction))
      return BOTTOM - fraction * (BOTTOM - TOP)
    },
  },
}
</script>

