<template>
  <section class="trf" :aria-label="heading">
    <header class="trf__head">
      <span class="trf__icon" aria-hidden="true">
        <v-icon :icon="mdiAccountGroupOutline" size="26" />
      </span>

      <div class="trf__heading">
        <h2 class="trf__title">{{ heading }}</h2>
        <span v-if="period" class="trf__period">
          <i class="trf__dot" aria-hidden="true"></i>
          {{ period }}
        </span>
      </div>
    </header>

    <ul class="trf__grid">
      <li v-for="(item, index) in items" :key="item.manager.id" class="trf__card" :style="{ '--mc': item.rgb, '--i': index }" tabindex="0">
        <span class="trf__shine" aria-hidden="true"></span>

        <div class="trf__top">
          <span class="trf__name">{{ item.manager.name }}</span>
          <span v-if="item.percent !== null" class="trf__pill">{{ number(item.percent, 1) }}%</span>
        </div>

        <div class="trf__gauge" role="img" :aria-label="`${item.manager.name}: ${item.percent === null ? '—' : number(item.percent, 1) + '%'}`">
          <svg viewBox="0 0 120 68" class="trf__svg" aria-hidden="true">
            <path class="trf__track" d="M 12 60 A 48 48 0 0 1 108 60" />
            <path
              class="trf__arc"
              d="M 12 60 A 48 48 0 0 1 108 60"
              :stroke-dasharray="arcLength"
              :stroke-dashoffset="offset(item)"
            />
          </svg>
          <div class="trf__center">
            <strong>{{ item.fact === null ? '—' : number(item.fact * progress, 0) }}</strong>
            <small>{{ $t('traffic.visitors') }}</small>
          </div>
        </div>

        <dl class="trf__stats">
          <div>
            <dt>{{ $t('kpi.plan') }}</dt>
            <dd>{{ number(item.plan, 0) }}</dd>
          </div>
          <div>
            <dt>{{ $t('traffic.pastShort') }}</dt>
            <dd>{{ number(item.past, 0) }}</dd>
          </div>
        </dl>

        <span v-if="item.delta !== null" class="trf__chip">
          <i aria-hidden="true">{{ item.delta >= 0 ? '▲' : '▼' }}</i>
          {{ item.delta >= 0 ? '+' : '' }}{{ Math.round(item.delta) }}% {{ $t('kpi.vsPast') }}
        </span>
      </li>
    </ul>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiAccountGroupOutline } from '@mdi/js'
import { useScopeStore } from '@/stores/scope'
import { completion, growth, statusOf } from '@/utils/kpi'
import { entryRgb } from '@/utils/color'

// Длина дуги-полукруга радиусом 48
const ARC_LENGTH = Math.PI * 48
const ANIMATION_MS = 1200
const STEP_MS = 16

export default {
  name: 'ManagersTraffic',

  data() {
    return {
      mdiAccountGroupOutline,
      arcLength: ARC_LENGTH,
      // Ход анимации появления от 0 до 1: по нему набегают числа и заполняются дуги
      progress: 0,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['current', 'kind']),
    ...mapState(useScopeStore, ['totals']),

    locale() {
      return this.$i18n.locale
    },

    heading() {
      return this.$t(this.kind === 'stores' ? 'traffic.titleStores' : 'traffic.title')
    },

    period() {
      return this.current ? this.current.time : ''
    },

    // Менеджеры или магазины от большего трафика к меньшему. Цвет карточки: у менеджера из конфигурации, у магазина по выполнению плана
    items() {
      const list = this.totals.map(({ manager, row }) => {
        const pick = (field) => (row && typeof row[field] === 'number' ? row[field] : null)
        const fact = pick('trafic_f')
        const plan = pick('trafic_p')
        const past = pick('trafic_past')
        const percent = completion(fact, plan)
        return {
          manager,
          rgb: entryRgb(this.kind, manager, statusOf(percent)),
          fact,
          plan,
          past,
          percent,
          delta: growth(fact, past),
        }
      })
      return list.sort((a, b) => (b.fact === null ? -1 : b.fact) - (a.fact === null ? -1 : a.fact))
    },

    // Меняется, когда пришли другие значения (например, выбран другой период): анимация проигрывается заново
    signature() {
      return this.items.map((item) => `${item.manager.id}:${item.fact}:${item.plan}`).join('|')
    },
  },

  watch: {
    signature() {
      this.reveal()
    },
  },

  mounted() {
    this.reveal()
  },

  beforeUnmount() {
    clearTimeout(this.startTimer)
    clearInterval(this.tween)
  },

  methods: {
    number(value, digits) {
      if (typeof value !== 'number') return '—'
      return new Intl.NumberFormat(this.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value)
    },

    // Смещение дуги: полная дуга — выполнение 100% и больше
    offset(item) {
      const filled = item.percent === null ? 0 : Math.min(item.percent, 100) / 100
      return ARC_LENGTH * (1 - filled * this.progress)
    },

    // Проигрывает появление; setInterval, а не requestAnimationFrame, чтобы работало и в фоновой вкладке
    reveal() {
      clearTimeout(this.startTimer)
      clearInterval(this.tween)
      this.progress = 0
      this.startTimer = setTimeout(() => {
        const started = Date.now()
        this.tween = setInterval(() => {
          const t = Math.min(1, (Date.now() - started) / ANIMATION_MS)
          this.progress = 1 - Math.pow(1 - t, 3)
          if (t === 1) clearInterval(this.tween)
        }, STEP_MS)
      }, 250)
    },
  },
}
</script>

