<template>
  <v-dialog
    :model-value="modelValue"
    width="880"
    max-width="calc(100vw - 32px)"
    transition="scale-transition"
    @update:model-value="$emit('update:modelValue', $event)"
    @after-leave="destroy"
  >
    <v-card v-if="metric" class="trend" rounded="xl">
      <span class="trend__bar" aria-hidden="true"></span>

      <header class="trend__head">
        <span class="trend__icon" aria-hidden="true">
          <v-icon :icon="metric.icon" size="26" />
        </span>

        <div class="trend__heading">
          <h2 class="trend__title">{{ $t(metric.title) }}</h2>
          <span class="trend__subtitle">{{ $t('kpi.trend') }}</span>
        </div>

        <div class="trend__tools">
          <div class="trend__switch" role="group">
            <button
              v-for="item in views"
              :key="item"
              type="button"
              class="trend__view"
              :class="{ 'trend__view--active': view === item }"
              :aria-pressed="view === item"
              @click="view = item"
            >
              {{ $t(`kpi.${item}`) }}
            </button>
          </div>
          <button type="button" class="trend__close" :aria-label="$t('kpi.close')" @click="$emit('update:modelValue', false)">
            <v-icon :icon="mdiClose" size="20" />
          </button>
        </div>
      </header>

      <p v-if="!periods.length" class="trend__empty">{{ $t('kpi.noPeriods') }}</p>

      <template v-else>
        <!-- Итоги последнего закрытого месяца: то, что обычно хочется увидеть первым -->
        <div class="trend__stats">
          <div class="trend__stat">
            <span>{{ $t('kpi.selectedPeriod') }} · {{ labels[selectedIndex] }}</span>
            <strong>{{ format(last[metric.fact]) }}</strong>
          </div>
          <div v-if="completionValue !== null" class="trend__stat" :class="`trend__stat--${completionState}`">
            <span>{{ $t('kpi.planCompletion') }}</span>
            <strong>{{ number(completionValue, 1) }}%</strong>
          </div>
          <div v-if="growthValue !== null" class="trend__stat" :class="growthValue >= 0 ? 'trend__stat--good' : 'trend__stat--bad'">
            <span>{{ $t('kpi.yoy') }}</span>
            <strong>
              <small aria-hidden="true">{{ growthValue >= 0 ? '▲' : '▼' }}</small>
              {{ growthValue >= 0 ? '+' : '' }}{{ number(growthValue, 1) }}%
            </strong>
          </div>
        </div>

        <ul v-if="view === 'chart'" class="trend__legend" :aria-label="$t('kpi.hideSeries')">
          <li v-for="item in series" :key="item.key">
            <button
              type="button"
              class="trend__legend-item"
              :class="{ 'trend__legend-item--off': hidden.includes(item.key) }"
              :aria-pressed="!hidden.includes(item.key)"
              @click="toggle(item.key)"
            >
              <span class="trend__swatch" :class="{ 'trend__swatch--dashed': item.dashed }" :style="{ '--color': item.color }"></span>
              {{ item.label }}
            </button>
          </li>
        </ul>

        <div v-show="view === 'chart'" class="trend__chart">
          <canvas ref="canvas"></canvas>
        </div>

        <div v-if="view === 'table'" class="trend__table-wrap">
          <table class="trend__table">
            <thead>
              <tr>
                <th>{{ $t('kpi.period') }}</th>
                <th v-for="item in series" :key="item.key">{{ item.label }}</th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="(row, index) in periods" :key="row.time">
                <th>{{ labels[index] }}</th>
                <td v-for="item in series" :key="item.key">{{ format(row[item.field]) }}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </template>
    </v-card>
  </v-dialog>
</template>

<script>
import { mapState } from 'pinia'
import { mdiClose } from '@mdi/js'
import Chart from '@/plugins/chart'
import { useSettingsStore } from '@/stores/settings'
import { completion, growth, statusOf } from '@/utils/kpi'

// Цвета рядов по слотам палитры данных: факт — синий, прошлый год — оранжевый, план — нейтральная пунктирная линия.
// Текст графика — цвета текста, а не рядов; цвет ряда несёт только маркер.
const COLORS = {
  light: {
    fact: '#2a78d6',
    past: '#eb6834',
    plan: '#8a8985',
    text: '#52514e',
    ink: '#0b0b0b',
    grid: 'rgba(11, 11, 11, 0.08)',
    cross: 'rgba(11, 11, 11, 0.25)',
    surface: '#ffffff',
    band: 'rgba(252, 202, 5, 0.22)',
  },
  dark: {
    fact: '#3987e5',
    past: '#d95926',
    plan: '#9a998f',
    text: '#c3c2b7',
    ink: '#ffffff',
    grid: 'rgba(255, 255, 255, 0.1)',
    cross: 'rgba(255, 255, 255, 0.3)',
    surface: '#20201e',
    band: 'rgba(252, 202, 5, 0.2)',
  },
}

// Полоса за выбранным периодом: видно, по какому периоду сейчас показана вся страница
const selectedBand = {
  id: 'selectedBand',
  beforeDatasetsDraw(chart, args, options) {
    const meta = chart.getDatasetMeta(0)
    const point = meta && meta.data[options.index]
    if (!point) return
    const { ctx, chartArea } = chart
    const step = chart.scales.x.width / Math.max(1, chart.data.labels.length)
    const width = Math.min(step * 0.7, 56)
    ctx.save()
    ctx.fillStyle = options.color
    ctx.beginPath()
    ctx.roundRect(point.x - width / 2, chartArea.top, width, chartArea.bottom - chartArea.top, 10)
    ctx.fill()
    ctx.restore()
  },
}

// Вертикальная линия в точке под курсором: вместе с подсказкой показывает, какой месяц выбран
const crosshair = {
  id: 'crosshair',
  afterDatasetsDraw(chart, args, options) {
    const active = chart.tooltip && chart.tooltip.getActiveElements()
    if (!active || !active.length) return
    const { ctx, chartArea } = chart
    const x = active[0].element.x
    ctx.save()
    ctx.beginPath()
    ctx.moveTo(x, chartArea.top)
    ctx.lineTo(x, chartArea.bottom)
    ctx.lineWidth = 1
    ctx.setLineDash([4, 4])
    ctx.strokeStyle = options.color
    ctx.stroke()
    ctx.restore()
  },
}

export default {
  name: 'KpiTrendDialog',

  props: {
    modelValue: {
      type: Boolean,
      default: false,
    },
    // Описание показателя из KPI_METRICS
    metric: {
      type: Object,
      default: null,
    },
    // Все строки таблицы компании
    rows: {
      type: Array,
      default: () => [],
    },
    // time периода, выбранного на странице
    selected: {
      type: String,
      default: '',
    },
  },

  emits: ['update:modelValue'],

  data() {
    return {
      mdiClose,
      views: ['chart', 'table'],
      view: 'chart',
      // Ряды, которые скрыты кликом по легенде
      hidden: [],
    }
  },

  computed: {
    ...mapState(useSettingsStore, ['isDark', 'locale']),

    palette() {
      return this.isDark ? COLORS.dark : COLORS.light
    },

    // Все периоды таблицы в её порядке, без пересчёта и объединения
    periods() {
      return this.rows
    },

    // Подпись периода — значение поля time как в таблице, без перевода
    labels() {
      return this.periods.map((row) => row.time)
    },

    // Номер выбранного периода; если такого нет — последний
    selectedIndex() {
      const index = this.periods.findIndex((row) => row.time === this.selected)
      return index >= 0 ? index : this.periods.length - 1
    },

    // Выбранный период
    last() {
      return this.periods[this.selectedIndex] || {}
    },

    completionValue() {
      return this.metric ? completion(this.last[this.metric.fact], this.last[this.metric.plan]) : null
    },

    completionState() {
      return statusOf(this.completionValue)
    },

    growthValue() {
      return this.metric && this.metric.past ? growth(this.last[this.metric.fact], this.last[this.metric.past]) : null
    },

    series() {
      if (!this.metric) return []
      const list = [
        { key: 'plan', field: this.metric.plan, label: this.$t('kpi.plan'), color: this.palette.plan, dashed: true },
        { key: 'fact', field: this.metric.fact, label: this.$t('kpi.fact'), color: this.palette.fact },
      ]
      if (this.metric.past) {
        list.push({ key: 'past', field: this.metric.past, label: this.$t('kpi.pastLabel'), color: this.palette.past })
      }
      return list
    },
  },

  watch: {
    view(value) {
      if (value === 'chart') this.$nextTick(this.draw)
    },

    // Цвета и подписи графика зависят от темы и языка
    isDark() {
      this.draw()
    },

    locale() {
      this.draw()
    },

    // Выбрали другой период на странице: подсветка на графике переезжает
    selected() {
      if (this.modelValue) this.draw()
    },

    metric() {
      this.hidden = []
      if (this.modelValue) this.$nextTick(this.draw)
    },

    // График рисуется, когда окно раскрылось: по таймеру, а не по событию перехода, которое может не прийти
    modelValue(open) {
      clearTimeout(this.drawTimer)
      if (open) this.drawTimer = setTimeout(this.draw, 350)
    },
  },

  beforeUnmount() {
    clearTimeout(this.drawTimer)
    this.destroy()
  },

  methods: {
    number(value, digits) {
      return new Intl.NumberFormat(this.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value)
    },

    format(value) {
      if (typeof value !== 'number') return '—'
      const text = this.number(value, this.metric ? this.metric.digits : 0)
      return this.metric && this.metric.suffix ? `${text}${this.metric.suffix}` : text
    },

    // Клик по легенде прячет или возвращает ряд
    toggle(key) {
      this.hidden = this.hidden.includes(key) ? this.hidden.filter((item) => item !== key) : [...this.hidden, key]
      if (!this.chart) return
      this.chart.data.datasets.forEach((dataset) => {
        this.chart.setDatasetVisibility(this.chart.data.datasets.indexOf(dataset), !this.hidden.includes(dataset.key))
      })
      this.chart.update()
    },

    destroy() {
      // Экземпляр графика хранится вне data(), чтобы Vue не делал его реактивным
      if (this.chart) this.chart.destroy()
      this.chart = null
    },

    draw(attempt = 0) {
      clearTimeout(this.drawTimer)
      this.destroy()
      if (!this.modelValue || !this.metric || !this.periods.length || !this.$refs.canvas) return

      // Окно ещё раскрывается и холст не имеет размера: пробуем чуть позже
      const wrap = this.$refs.canvas.parentElement
      if (wrap && wrap.clientWidth === 0 && attempt < 10) {
        this.drawTimer = setTimeout(() => this.draw(attempt + 1), 100)
        return
      }

      const colors = this.palette
      const compact = new Intl.NumberFormat(this.locale, { notation: 'compact', maximumFractionDigits: 1 })
      // Точка выбранного периода крупнее и подписана значением
      const lastIndex = this.selectedIndex

      this.chart = new Chart(this.$refs.canvas, {
        type: 'line',
        plugins: [crosshair, selectedBand],
        data: {
          labels: this.labels,
          datasets: this.series.map((item) => {
            const isFact = item.key === 'fact'
            return {
              key: item.key,
              label: item.label,
              data: this.periods.map((row) => (typeof row[item.field] === 'number' ? row[item.field] : null)),
              hidden: this.hidden.includes(item.key),
              borderColor: item.color,
              // Под линией факта мягкая заливка, уходящая в прозрачность
              fill: isFact ? 'origin' : false,
              backgroundColor: isFact
                ? (context) => {
                    const { ctx, chartArea } = context.chart
                    if (!chartArea) return 'transparent'
                    const gradient = ctx.createLinearGradient(0, chartArea.top, 0, chartArea.bottom)
                    gradient.addColorStop(0, `${item.color}44`)
                    gradient.addColorStop(1, `${item.color}00`)
                    return gradient
                  }
                : item.color,
              borderWidth: 2.5,
              borderDash: item.dashed ? [6, 5] : [],
              pointRadius: item.dashed ? 0 : (context) => (context.dataIndex === lastIndex ? 6 : 4),
              pointHoverRadius: 7,
              pointBackgroundColor: item.color,
              pointBorderColor: colors.surface,
              pointBorderWidth: 2,
              tension: 0,
              spanGaps: true,
              // Подпись только у последней точки факта: значение видно сразу, остальное — в подсказке
              datalabels: {
                display: (context) => isFact && context.dataIndex === lastIndex,
                anchor: 'end',
                align: 'top',
                offset: 8,
                // Подпись последней точки не выходит за край графика
                clamp: true,
                color: colors.ink,
                font: { weight: 800, size: 12 },
                backgroundColor: colors.surface,
                borderColor: item.color,
                borderWidth: 1.5,
                borderRadius: 8,
                padding: { top: 3, bottom: 3, left: 7, right: 7 },
                formatter: (value) => this.format(value),
              },
            }
          }),
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: { mode: 'index', intersect: false },
          layout: { padding: { top: 30, right: 52, left: 4 } },
          animation: { duration: 1100, easing: 'easeOutQuart' },
          plugins: {
            // Легенда — своя, в HTML
            legend: { display: false },
            datalabels: { display: false },
            crosshair: { color: colors.cross },
            selectedBand: { index: this.selectedIndex, color: colors.band },
            tooltip: {
              backgroundColor: colors.surface,
              titleColor: colors.ink,
              bodyColor: colors.text,
              footerColor: colors.text,
              borderColor: colors.grid,
              borderWidth: 1,
              padding: 12,
              cornerRadius: 12,
              boxPadding: 6,
              usePointStyle: true,
              titleFont: { weight: 800, size: 13 },
              footerFont: { weight: 600, size: 12 },
              callbacks: {
                label: (context) => ` ${context.dataset.label}: ${this.format(context.parsed.y)}`,
                // Под значениями: выполнение плана и рост к прошлому году в выбранном месяце
                footer: (items) => {
                  const row = this.periods[items[0].dataIndex]
                  const done = completion(row[this.metric.fact], row[this.metric.plan])
                  const yoy = this.metric.past ? growth(row[this.metric.fact], row[this.metric.past]) : null
                  const lines = []
                  if (done !== null) lines.push(`${this.$t('kpi.planCompletion')}: ${this.number(done, 1)}%`)
                  if (yoy !== null) lines.push(`${this.$t('kpi.yoy')}: ${yoy >= 0 ? '+' : ''}${this.number(yoy, 1)}%`)
                  return lines
                },
              },
            },
          },
          scales: {
            x: { grid: { display: false }, border: { display: false }, ticks: { color: colors.text, font: { weight: 600 } } },
            y: {
              grid: { color: colors.grid },
              border: { display: false },
              ticks: {
                color: colors.text,
                maxTicksLimit: 6,
                callback: (value) => (this.metric.digits === 0 ? compact.format(value) : value),
              },
            },
          },
        },
      })
    },
  },
}
</script>

