<template>
  <div class="layout">
    <loading-screen />
    <app-sidebar v-model="drawer" :rail="rail" />
    <app-header :rail="rail" @toggle="toggleSidebar" />
    <period-picker />

    <div class="layout__body">
      <div class="layout__content">
        <router-view v-slot="{ Component }">
          <transition name="page" mode="out-in">
            <component :is="Component" />
          </transition>
        </router-view>
      </div>

      <app-footer />
    </div>
  </div>
</template>

<script>
import AppFooter from '@/components/AppFooter.vue'
import AppHeader from '@/components/AppHeader.vue'
import AppSidebar from '@/components/AppSidebar.vue'
import LoadingScreen from '@/components/LoadingScreen.vue'
import PeriodPicker from '@/components/PeriodPicker.vue'
import { STORAGE_KEYS } from '@/configurations'
import { useSourcesStore } from '@/stores/sources'
import { readStorage, writeStorage } from '@/utils/storage'

export default {
  name: 'DashboardLayout',

  components: { AppFooter, AppHeader, AppSidebar, LoadingScreen, PeriodPicker },

  data() {
    return {
      // Выдвижной сайдбар (телефон и планшет)
      drawer: false,
      // Узкий сайдбар (компьютер): по умолчанию свёрнут, пока пользователь сам не раскроет; выбор запоминается
      rail: readStorage(STORAGE_KEYS.SIDEBAR_RAIL) !== false,
    }
  },

  // Сразу после входа запускается загрузка основных данных: компания и каждый менеджер из MANAGERS.
  // Курс и погода второстепенные, они грузятся сами и дашборд не задерживают.
  created() {
    useSourcesStore().start()
  },

  beforeUnmount() {
    useSourcesStore().stop()
  },

  methods: {
    toggleSidebar() {
      if (this.$vuetify.display.mdAndUp) {
        this.rail = !this.rail
        writeStorage(STORAGE_KEYS.SIDEBAR_RAIL, this.rail)
      } else {
        this.drawer = !this.drawer
      }
    },
  },
}
</script>

