<template>
  <article
    class="kpi"
    :class="[`kpi--${state}`, { 'kpi--hover': hovering }]"
    :style="cardStyle"
    @pointermove="onMove"
    @pointerleave="onLeave"
  >
    <header class="kpi__head">
      <span class="kpi__icon" aria-hidden="true">
        <v-icon :icon="metric.icon" size="22" />
      </span>

      <div class="kpi__heading">
        <h3 class="kpi__title">{{ $t(metric.title) }}</h3>
        <span v-if="period" class="kpi__period">
          <i class="kpi__dot" aria-hidden="true"></i>
          {{ period }}
        </span>
      </div>

      <button
        type="button"
        class="kpi__trend"
        :aria-label="`${$t(metric.title)}: ${$t('kpi.trend')}`"
        :disabled="loading"
        @click="$emit('trend')"
      >
        <v-icon :icon="mdiChartLine" size="18" />
        <v-tooltip activator="parent" location="top" :text="$t('kpi.trend')" />
      </button>
    </header>

    <div v-if="loading" class="kpi__main">
      <div class="kpi__nums">
        <span class="kpi__skeleton kpi__skeleton--thin"></span>
        <span class="kpi__skeleton kpi__skeleton--hero"></span>
        <span class="kpi__skeleton kpi__skeleton--thin"></span>
      </div>
      <div class="kpi__ring kpi__ring--wait">
        <v-progress-circular indeterminate size="34" width="3" />
      </div>
    </div>

    <template v-else>
      <div class="kpi__main">
        <div class="kpi__nums">
          <span class="kpi__label">{{ $t('kpi.fact') }}</span>
          <strong class="kpi__hero">{{ value(shownFact) }}</strong>
          <span class="kpi__plan">
            {{ $t('kpi.plan') }}
            <b>{{ value(row && row[metric.plan]) }}</b>
          </span>
        </div>

        <liquid-orb
          class="kpi__ring"
          :uid="gradientId"
          :fraction="filled"
          :over="percent !== null && percent > 100"
          :text="percent === null ? '—' : `${number(shownPercent, 1)}%`"
          :caption="$t('kpi.done')"
          :label="`${$t(metric.title)}: ${ringText}`"
        />
      </div>

      <footer v-if="bottom || delta !== null || shareText" class="kpi__foot">
        <div v-if="bottom" class="kpi__past">
          <span>{{ bottom.label }}</span>
          <b>{{ bottom.value }}</b>
        </div>

        <div v-if="delta !== null || shareText" class="kpi__chips">
          <span v-if="delta !== null" class="kpi__chip" :class="delta >= 0 ? 'kpi__chip--up' : 'kpi__chip--down'">
            <span aria-hidden="true">{{ delta >= 0 ? '▲' : '▼' }}</span>
            {{ delta >= 0 ? '+' : '' }}{{ Math.round(delta) }}% {{ $t('kpi.vsPast') }}
          </span>
          <span v-if="shareText" class="kpi__chip kpi__chip--share">{{ shareText }}</span>
        </div>
      </footer>
    </template>
  </article>
</template>

<script>
import { mdiChartLine } from '@mdi/js'
import LiquidOrb from '@/components/LiquidOrb.vue'
import { completion, growth, statusOf } from '@/utils/kpi'

const ANIMATION_MS = 1200
const STEP_MS = 16

export default {
  name: 'KpiCard',

  components: { LiquidOrb },

  props: {
    // Описание показателя из KPI_METRICS
    metric: {
      type: Object,
      required: true,
    },
    // Строка таблицы за выбранный период; null, пока данные не загрузились
    row: {
      type: Object,
      default: null,
    },
    // Порядковый номер карточки: задаёт задержку появления
    index: {
      type: Number,
      default: 0,
    },
    loading: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['trend'],

  data() {
    return {
      mdiChartLine,
      // Ход анимации появления от 0 до 1: по нему «набегают» число и процент и заполняется кольцо
      progress: 0,
      hovering: false,
      // Наклон карточки за курсором и положение блика
      tilt: { rx: 0, ry: 0, mx: 50, my: 50 },
    }
  },

  computed: {
    locale() {
      return this.$i18n.locale
    },

    period() {
      return this.row ? this.row.time : ''
    },

    fact() {
      return this.row && typeof this.row[this.metric.fact] === 'number' ? this.row[this.metric.fact] : null
    },

    percent() {
      return this.row ? completion(this.row[this.metric.fact], this.row[this.metric.plan]) : null
    },

    // Меняется, когда пришли новые значения: тогда анимация проигрывается заново
    signature() {
      return `${this.fact}|${this.percent}`
    },

    shownPercent() {
      return this.percent === null ? 0 : this.percent * this.progress
    },

    shownFact() {
      return this.fact === null ? null : this.fact * this.progress
    },

    state() {
      return this.loading ? 'none' : statusOf(this.percent)
    },

    delta() {
      if (!this.row || !this.metric.past) return null
      return growth(this.row[this.metric.fact], this.row[this.metric.past])
    },

    gradientId() {
      return `kpi-gradient-${this.metric.id}`
    },

    // Кольцо показывает не больше полного круга, даже если план перевыполнен
    filled() {
      return this.percent === null ? 0 : (Math.min(this.percent, 100) / 100) * this.progress
    },

    ringText() {
      return this.percent === null ? '—' : `${this.number(this.percent, 1)}%`
    },

    // Нижняя строка: прошлый год, а у кредита — итоговая сумма
    bottom() {
      if (!this.row) return null
      if (this.metric.sum) {
        return { label: this.$t('kpi.sum'), value: this.number(this.row[this.metric.sum], 0) }
      }
      if (!this.metric.past) return null
      const past = this.row[this.metric.past]
      if (typeof past !== 'number') return null
      const million = this.metric.compactPast && Math.abs(past) >= 1e6
      return {
        label: this.$t('kpi.factPast'),
        value: million ? `${this.number(past / 1e6, 2)} ${this.$t('kpi.million')}` : this.value(past),
      }
    },

    shareText() {
      if (!this.row || !this.metric.share) return ''
      const total = this.row[this.metric.share]
      const part = this.row[this.metric.fact]
      if (typeof total !== 'number' || typeof part !== 'number' || total === 0) return ''
      return `${Math.round((part / total) * 100)}% ${this.$t('kpi.shareOfTotal')}`
    },

    cardStyle() {
      const { rx, ry, mx, my } = this.tilt
      return { '--i': this.index, '--rx': `${rx}deg`, '--ry': `${ry}deg`, '--mx': `${mx}%`, '--my': `${my}%` }
    },
  },

  watch: {
    // Данные пришли или изменились: анимация начинается с нуля
    loading(value) {
      if (!value) this.reveal()
    },

    signature() {
      if (!this.loading) this.reveal()
    },
  },

  mounted() {
    if (!this.loading) this.reveal()
  },

  beforeUnmount() {
    clearTimeout(this.startTimer)
    clearInterval(this.tween)
  },

  methods: {
    number(value, digits) {
      if (typeof value !== 'number') return '—'
      return new Intl.NumberFormat(this.locale, {
        minimumFractionDigits: digits,
        maximumFractionDigits: digits,
      }).format(value)
    },

    // Значение с нужным числом знаков и единицей показателя
    value(value) {
      const text = this.number(value, this.metric.digits)
      return typeof value === 'number' && this.metric.suffix ? `${text}${this.metric.suffix}` : text
    },

    // Проигрывает появление; setInterval, а не requestAnimationFrame, чтобы работало и в фоновой вкладке
    reveal() {
      clearTimeout(this.startTimer)
      clearInterval(this.tween)
      this.progress = 0
      this.startTimer = setTimeout(() => {
        const started = Date.now()
        this.tween = setInterval(() => {
          const t = Math.min(1, (Date.now() - started) / ANIMATION_MS)
          this.progress = 1 - Math.pow(1 - t, 3)
          if (t === 1) clearInterval(this.tween)
        }, STEP_MS)
      }, 200 + this.index * 70)
    },

    // Наклон карточки за курсором мыши; на сенсорных экранах не нужен
    onMove(event) {
      if (event.pointerType !== 'mouse') return
      const rect = event.currentTarget.getBoundingClientRect()
      const x = (event.clientX - rect.left) / rect.width
      const y = (event.clientY - rect.top) / rect.height
      this.hovering = true
      this.tilt = { rx: (0.5 - y) * 6, ry: (x - 0.5) * 8, mx: x * 100, my: y * 100 }
    },

    onLeave() {
      this.hovering = false
      this.tilt = { rx: 0, ry: 0, mx: 50, my: 50 }
    },
  },
}
</script>

