import { normalizeRows } from '@/services/company'
import { gasGet } from '@/services/gas'

// Таблица менеджера в порядке скрипта: периоды идут подряд, внутри периода первая строка — итог менеджера,
// дальше его магазины (столбец company). Все столбцы те же, что у компании, кроме интернет-магазина и мономаркета.
export async function fetchManager(manager) {
  const data = await gasGet(manager.url)
  let list = data && manager.dataKey ? data[manager.dataKey] : null
  // Если ключ не указан или изменился, берём первый массив из ответа
  if (!Array.isArray(list) && data) list = Object.values(data).find(Array.isArray)
  if (!Array.isArray(list)) throw new Error(`Manager ${manager.id}: неожиданный ответ`)
  return normalizeRows(list)
}
