import { API, WEATHER } from '@/configurations'

// Текущая погода в точке (query — «широта,долгота») на языке lang: ru, uk или en.
// Возвращает только те поля, что нужны интерфейсу; при сбое бросает ошибку.
export async function fetchWeather(query, lang) {
  const params = new URLSearchParams({ key: WEATHER.KEY, q: query, lang, aqi: 'no' })
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), API.TIMEOUT)

  try {
    const response = await fetch(`${WEATHER.URL}?${params}`, { signal: controller.signal })
    if (!response.ok) throw new Error(`Weather ${response.status}`)

    const { current } = await response.json()
    if (!current || typeof current.temp_c !== 'number') throw new Error('Weather: пустой ответ')

    return {
      temp: current.temp_c,
      feelsLike: current.feelslike_c,
      condition: current.condition.text,
      // API отдаёт адрес без протокола и в размере 64x64; для карточки берём крупную иконку
      icon: `https:${current.condition.icon}`,
      iconLarge: `https:${current.condition.icon.replace('/64x64/', '/128x128/')}`,
      isDay: current.is_day === 1,
      humidity: current.humidity,
      windMs: current.wind_kph / 3.6,
      windDir: current.wind_dir,
      windDegree: current.wind_degree,
      pressureMmHg: current.pressure_mb * 0.750062,
      visibilityKm: current.vis_km,
      uv: current.uv,
      updated: current.last_updated.slice(-5),
    }
  } finally {
    clearTimeout(timer)
  }
}
