<template>
  <v-menu location="bottom end" :offset="10" :close-on-content-click="false" transition="scale-transition">
    <template #activator="{ props, isActive }">
      <v-btn
        v-bind="props"
        class="rates__chip"
        :class="{ 'rates__chip--open': isActive }"
        :aria-label="$t('rates.title')"
        variant="flat"
        rounded="pill"
      >
        <span class="rates__coin" aria-hidden="true">{{ main.symbol }}</span>
        <span class="rates__main">
          <transition name="rates-swap" mode="out-in">
            <span v-if="loaded" :key="main.code" class="rates__value">{{ format(rates[main.code], 2) }}</span>
            <span v-else class="rates__value rates__value--wait">
              <v-progress-circular indeterminate size="14" width="2" />
            </span>
          </transition>
          <span class="rates__unit">{{ $t('rates.unit') }}</span>
        </span>
        <v-icon :icon="mdiChevronDown" size="18" class="rates__arrow" />
      </v-btn>
    </template>

    <v-card class="rates__card" rounded="xl" elevation="8" min-width="300">
      <header class="rates__head">
        <span class="rates__title">{{ $t('rates.title') }}</span>
        <span class="rates__badge">{{ $t('rates.source') }}</span>
      </header>

      <ul v-if="loaded" class="rates__list">
        <li v-for="(item, index) in currencies" :key="item.code" class="rates__item" :style="{ '--i': index }">
          <span class="rates__coin rates__coin--big" aria-hidden="true">{{ item.symbol }}</span>
          <span class="rates__name">
            <strong>{{ item.code }}</strong>
            <small>{{ $t(`currency.${item.code}`) }}</small>
          </span>
          <span class="rates__price">
            {{ format(rates[item.code], 4) }}
            <small>{{ $t('rates.unit') }}</small>
          </span>
        </li>
      </ul>

      <div v-else class="rates__state">
        <v-progress-circular indeterminate size="28" width="3" />
      </div>

      <footer v-if="loaded" class="rates__foot">
        <span>{{ $t('rates.official', { date }) }}</span>
        <a :href="siteUrl" target="_blank" rel="noopener noreferrer" :aria-label="$t('rates.open')">
          <v-icon :icon="mdiOpenInNew" size="14" />
        </a>
      </footer>
    </v-card>
  </v-menu>
</template>

<script>
import { mapActions, mapState } from 'pinia'
import { mdiChevronDown, mdiOpenInNew } from '@mdi/js'
import { NBU } from '@/configurations'
import { useRatesStore } from '@/stores/rates'

export default {
  name: 'HeaderRates',

  data() {
    return {
      mdiChevronDown,
      mdiOpenInNew,
      currencies: NBU.CURRENCIES,
      siteUrl: NBU.SITE_URL,
    }
  },

  computed: {
    ...mapState(useRatesStore, ['rates', 'date', 'loaded']),

    // Валюта, которая видна в шапке без открытия списка
    main() {
      return this.currencies[0]
    },
  },

  mounted() {
    this.load()
    this.scheduleNext()
  },

  beforeUnmount() {
    clearTimeout(this.timer)
    this.cancelRetry()
  },

  methods: {
    ...mapActions(useRatesStore, ['load', 'cancelRetry']),

    // Обновление в заданные часы из NBU.REFRESH_TIMES; после каждого запроса ждём следующего времени
    scheduleNext() {
      const now = new Date()
      const times = NBU.REFRESH_TIMES.map((time) => {
        const [hours, minutes] = time.split(':').map(Number)
        const at = new Date(now)
        at.setHours(hours, minutes, 0, 0)
        return at
      })
      const next = times.find((at) => at > now) || new Date(times[0].getTime() + 24 * 60 * 60 * 1000)
      this.timer = setTimeout(() => {
        this.load()
        this.scheduleNext()
      }, next - now)
    },

    format(value, digits) {
      return new Intl.NumberFormat(this.$i18n.locale, {
        minimumFractionDigits: digits,
        maximumFractionDigits: digits,
      }).format(value)
    },
  },
}
</script>

