<template>
  <div v-if="$route.name !== 'forbidden'" class="picker" :class="{ 'picker--dark': isDark }">
    <v-menu location="bottom end" :offset="10" transition="scale-transition">
      <template #activator="{ props, isActive }">
        <button
          v-bind="props"
          type="button"
          class="picker__btn"
          :class="{ 'picker__btn--open': isActive }"
          :aria-label="`${$t('period.choose')}: ${label}`"
          :title="$t('period.title')"
          :disabled="!rows.length"
        >
          <span class="picker__icon" aria-hidden="true">
            <v-icon :icon="mdiCalendarRange" size="16" />
          </span>

          <span class="picker__text">
            <transition name="picker-swap" mode="out-in">
              <strong :key="label">{{ label }}</strong>
            </transition>
          </span>

          <v-progress-circular v-if="!rows.length" indeterminate size="16" width="2" />
          <v-icon v-else :icon="mdiChevronDown" size="16" class="picker__arrow" />
        </button>
      </template>

      <v-card class="picker__card" rounded="xl" elevation="8" min-width="240">
        <p class="picker__head">{{ $t('period.choose') }}</p>

        <ul class="picker__list" role="listbox" :aria-label="$t('period.choose')">
          <li
            v-for="(row, index) in ordered"
            :key="row.time"
            class="picker__item"
            :class="{ 'picker__item--active': row.time === selected }"
            :style="{ '--i': index }"
            role="option"
            tabindex="0"
            :aria-selected="row.time === selected"
            @click="selectPeriod(row.time)"
            @keydown.enter.prevent="selectPeriod(row.time)"
            @keydown.space.prevent="selectPeriod(row.time)"
          >
            <span class="picker__dot" aria-hidden="true"></span>
            <span class="picker__time">{{ row.time }}</span>
            <span v-if="row.time === latestTime" class="picker__badge">{{ $t('period.latest') }}</span>
            <v-icon :icon="mdiCheck" size="18" class="picker__check" />
          </li>
        </ul>
      </v-card>
    </v-menu>
  </div>
</template>

<script>
import { mapActions, mapState } from 'pinia'
import { mdiCalendarRange, mdiCheck, mdiChevronDown } from '@mdi/js'
import { useScopeStore } from '@/stores/scope'
import { useSettingsStore } from '@/stores/settings'

export default {
  name: 'PeriodPicker',

  data() {
    return {
      mdiCalendarRange,
      mdiCheck,
      mdiChevronDown,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['rows', 'current', 'latest']),
    ...mapState(useSettingsStore, ['isDark']),

    // В списке сверху самый свежий период, дальше в обратном порядке таблицы
    ordered() {
      return [...this.rows].reverse()
    },

    // Период показывается так, как он записан в таблице
    label() {
      return this.current ? this.current.time : '—'
    },

    selected() {
      return this.current ? this.current.time : ''
    },

    latestTime() {
      return this.latest ? this.latest.time : ''
    },
  },

  methods: {
    ...mapActions(useScopeStore, { selectPeriod: 'select' }),
  },
}
</script>

