<template>
  <section class="cnv" :class="{ 'cnv--dense': dense }" :aria-label="heading">
    <panel-head :icon="mdiPercentOutline" :title="heading" :period="period" />

    <ul class="cnv__legend">
      <li><span class="cnv__swatch cnv__swatch--fact"></span>{{ $t('kpi.fact') }}</li>
      <li><span class="cnv__swatch cnv__swatch--past"></span>{{ $t('traffic.pastShort') }}</li>
      <li><span class="cnv__swatch cnv__swatch--plan"></span>{{ $t('kpi.plan') }}</li>
    </ul>

    <ul class="cnv__rows">
      <li v-for="(item, index) in items" :key="item.manager.id" class="cnv__row" :style="{ '--mc': item.rgb, '--i': index }">
        <span class="cnv__name">
          <i class="cnv__dot" aria-hidden="true"></i>
          {{ item.manager.name }}
        </span>

        <div class="cnv__body">
          <!-- Дорожка 0–максимум: факт кружком, план чёрточкой с подписью, прошлый год точкой -->
          <div class="cnv__plot">
            <span v-if="item.plan !== null" class="cnv__plan-label" :style="{ left: `${pos(item.plan)}%` }">{{ percent(item.plan) }}%</span>

            <div class="cnv__track">
              <span class="cnv__fill" :style="{ width: `${pos(item.fact)}%` }"></span>
              <span v-if="item.plan !== null" class="cnv__plan" :style="{ left: `${pos(item.plan)}%` }" aria-hidden="true"></span>
              <span v-if="item.past !== null" class="cnv__past" :style="{ left: `${pos(item.past)}%` }" aria-hidden="true"></span>
              <span v-if="item.fact !== null" class="cnv__marker" :style="{ left: `${pos(item.fact)}%` }">{{ number(item.fact, 1) }}</span>
            </div>
          </div>

          <div class="cnv__axis" aria-hidden="true">
            <span>0%</span>
            <span>{{ top }}%</span>
          </div>

          <div class="cnv__foot">
            <b v-if="item.percent !== null" class="cnv__status" :class="`cnv__status--${item.state}`">
              <i aria-hidden="true">{{ item.percent >= 100 ? '▲' : '▼' }}</i>
              {{ number(item.percent, 1) }}% {{ $t('conversion.ofPlan') }}
            </b>
            <span v-if="item.past !== null" class="cnv__past-text">{{ $t('traffic.pastShort') }}: {{ percent(item.past) }}%</span>
          </div>
        </div>
      </li>
    </ul>
  </section>
</template>

<script>
import { mapState } from 'pinia'
import { mdiPercentOutline } from '@mdi/js'
import PanelHead from '@/components/PanelHead.vue'
import { useScopeStore } from '@/stores/scope'
import { DENSE_FROM, completion, statusOf } from '@/utils/kpi'
import { entryRgb } from '@/utils/color'

export default {
  name: 'ConversionByManagers',

  components: { PanelHead },

  data() {
    return {
      mdiPercentOutline,
      // Кружки и заливка едут от нуля после появления блока
      ready: false,
    }
  },

  computed: {
    ...mapState(useScopeStore, ['current', 'kind']),
    ...mapState(useScopeStore, ['totals']),

    locale() {
      return this.$i18n.locale
    },

    // Много строк (магазины): строки компактные
    dense() {
      return this.totals.length > DENSE_FROM
    },

    heading() {
      return this.$t(this.kind === 'stores' ? 'conversion.titleStores' : 'conversion.title')
    },

    period() {
      return this.current ? this.current.time : ''
    },

    // Менеджеры от большей конверсии к меньшей
    items() {
      const list = this.totals.map(({ manager, row }) => {
        const pick = (field) => (row && typeof row[field] === 'number' ? row[field] : null)
        const fact = pick('conver_f')
        const plan = pick('conver_p')
        const percent = completion(fact, plan)
        return { manager, rgb: entryRgb(this.kind, manager, statusOf(percent)), fact, plan, past: pick('conver_past'), percent, state: statusOf(percent) }
      })
      return list.sort((a, b) => (b.fact === null ? -1 : b.fact) - (a.fact === null ? -1 : a.fact))
    },

    // Верх шкалы в процентах: самое большое значение, округлённое вверх до 5
    top() {
      const values = this.items.flatMap((item) => [item.fact, item.plan, item.past]).filter((value) => typeof value === 'number')
      return Math.max(5, Math.ceil((Math.max(0, ...values) * 1.05) / 5) * 5)
    },
  },

  mounted() {
    this.readyTimer = setTimeout(() => (this.ready = true), 350)
  },

  beforeUnmount() {
    clearTimeout(this.readyTimer)
  },

  methods: {
    number(value, digits) {
      if (typeof value !== 'number') return '—'
      return new Intl.NumberFormat(this.locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value)
    },

    // Значение конверсии в процентах с одним знаком
    percent(value) {
      return this.number(value, 1)
    },

    // Положение на дорожке в процентах её длины; пока блок не появился, всё стоит в нуле
    pos(value) {
      return this.ready && typeof value === 'number' ? Math.min(100, (value / this.top) * 100) : 0
    },
  },
}
</script>

