<template>
  <v-menu location="bottom end" :offset="10" transition="scale-transition">
    <template #activator="{ props, isActive }">
      <button
        v-bind="props"
        type="button"
        class="lang__chip"
        :class="{ 'lang__chip--open': isActive }"
        :aria-label="$t('common.language')"
      >
        <span class="lang__badge">
          <v-icon :icon="mdiTranslate" size="16" />
        </span>
        <transition name="lang-swap" mode="out-in">
          <span :key="locale" class="lang__code">{{ locale.toUpperCase() }}</span>
        </transition>
        <v-icon :icon="mdiChevronDown" size="18" class="lang__arrow" />
      </button>
    </template>

    <v-card class="lang__card" rounded="xl" elevation="8" min-width="220">
      <ul class="lang__list" role="listbox" :aria-label="$t('common.language')">
        <li
          v-for="(item, index) in locales"
          :key="item.code"
          class="lang__item"
          :class="{ 'lang__item--active': item.code === locale }"
          :style="{ '--i': index }"
          role="option"
          tabindex="0"
          :aria-selected="item.code === locale"
          @click="setLocale(item.code)"
          @keydown.enter.prevent="setLocale(item.code)"
          @keydown.space.prevent="setLocale(item.code)"
        >
          <span class="lang__short">{{ item.code.toUpperCase() }}</span>
          <span class="lang__title">{{ item.title }}</span>
          <v-icon :icon="mdiCheck" size="18" class="lang__check" />
        </li>
      </ul>
    </v-card>
  </v-menu>
</template>

<script>
import { mapActions, mapState } from 'pinia'
import { mdiCheck, mdiChevronDown, mdiTranslate } from '@mdi/js'
import { useSettingsStore } from '@/stores/settings'

export default {
  name: 'HeaderLanguage',

  data() {
    return {
      mdiCheck,
      mdiChevronDown,
      mdiTranslate,
    }
  },

  computed: {
    ...mapState(useSettingsStore, ['locale', 'locales']),
  },

  methods: {
    ...mapActions(useSettingsStore, ['setLocale']),
  },
}
</script>

