<template>
  <article
    class="channel"
    :class="[`channel--${state}`, `channel--${metric.pattern}`]"
    :style="{ '--i': index, '--accent': metric.accent }"
  >
    <header class="channel__head">
      <span class="channel__icon" aria-hidden="true">
        <v-icon :icon="metric.icon" size="24" />
      </span>

      <div class="channel__heading">
        <h3 class="channel__title">{{ $t(metric.title) }}</h3>
        <span v-if="period" class="channel__period">
          <i class="channel__dot" aria-hidden="true"></i>
          {{ period }}
        </span>
      </div>

      <span v-if="percent !== null" class="channel__badge">{{ number(percent, 1) }}%</span>

      <button
        type="button"
        class="channel__trend"
        :aria-label="`${$t(metric.title)}: ${$t('kpi.trend')}`"
        :disabled="loading"
        @click="$emit('trend')"
      >
        <v-icon :icon="mdiChartLine" size="18" />
        <v-tooltip activator="parent" location="top" :text="$t('kpi.trend')" />
      </button>
    </header>

    <div v-if="loading" class="channel__wait">
      <span class="channel__skeleton channel__skeleton--hero"></span>
      <span class="channel__skeleton"></span>
      <span class="channel__skeleton channel__skeleton--thin"></span>
    </div>

    <template v-else>
      <div class="channel__hero">
        <strong>{{ number(shownFact, 0) }}</strong>
        <span>{{ $t('kpi.uah') }}</span>
      </div>

      <div class="channel__progress">
        <div class="channel__progress-head">
          <span>{{ $t('kpi.planCompletion') }}</span>
          <b>{{ percent === null ? '—' : `${number(shownPercent, 1)}%` }}</b>
        </div>

        <!-- Шкала до максимума из 100% и факта; чёрточка — план, всё правее неё — перевыполнение -->
        <div
          class="channel__bar"
          role="progressbar"
          aria-valuemin="0"
          aria-valuemax="100"
          :aria-valuenow="percent === null ? 0 : Math.round(percent)"
          :aria-label="$t('kpi.planCompletion')"
        >
          <span class="channel__fill" :style="{ width: `${fillWidth}%` }"></span>
          <span class="channel__mark" :style="{ left: `${markLeft}%` }"></span>
        </div>

        <span class="channel__compact">{{ compactText }}</span>
      </div>

      <footer class="channel__foot">
        <div class="channel__cell">
          <span>{{ $t('kpi.plan') }}</span>
          <b>{{ number(row && row[metric.plan], 0) }}</b>
        </div>

        <div v-if="past !== null" class="channel__cell">
          <span>{{ $t('kpi.factPast') }}</span>
          <b>{{ number(past, 0) }}</b>
        </div>

        <span v-if="delta !== null" class="channel__chip" :class="delta >= 0 ? 'channel__chip--up' : 'channel__chip--down'">
          <span aria-hidden="true">{{ delta >= 0 ? '▲' : '▼' }}</span>
          {{ delta >= 0 ? '+' : '' }}{{ Math.round(delta) }}% {{ $t('kpi.vsPast') }}
        </span>
      </footer>
    </template>
  </article>
</template>

<script>
import { mdiChartLine } from '@mdi/js'
import { completion, growth, statusOf } from '@/utils/kpi'

const ANIMATION_MS = 1200
const STEP_MS = 16

export default {
  name: 'ChannelCard',

  props: {
    // Описание канала из CHANNEL_METRICS
    metric: {
      type: Object,
      required: true,
    },
    // Строка таблицы за выбранный период; null, пока данные не загрузились
    row: {
      type: Object,
      default: null,
    },
    // Порядковый номер: задаёт задержку появления
    index: {
      type: Number,
      default: 0,
    },
    loading: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['trend'],

  data() {
    return {
      mdiChartLine,
      // Ход анимации появления от 0 до 1: по нему «набегают» числа и растёт шкала
      progress: 0,
    }
  },

  computed: {
    locale() {
      return this.$i18n.locale
    },

    period() {
      return this.row ? this.row.time : ''
    },

    fact() {
      return this.row && typeof this.row[this.metric.fact] === 'number' ? this.row[this.metric.fact] : null
    },

    plan() {
      return this.row && typeof this.row[this.metric.plan] === 'number' ? this.row[this.metric.plan] : null
    },

    // У мономаркета прошлого года до сентября нет: тогда строку и сравнение не показываем
    past() {
      const value = this.row ? this.row[this.metric.past] : null
      return typeof value === 'number' ? value : null
    },

    percent() {
      return completion(this.fact, this.plan)
    },

    // Меняется, когда пришли новые значения: тогда анимация проигрывается заново
    signature() {
      return `${this.fact}|${this.percent}`
    },

    shownPercent() {
      return this.percent === null ? 0 : this.percent * this.progress
    },

    shownFact() {
      return this.fact === null ? null : this.fact * this.progress
    },

    state() {
      return this.loading ? 'none' : statusOf(this.percent)
    },

    delta() {
      return growth(this.fact, this.past)
    },

    // Шкала растягивается, если план перевыполнен: чёрточка плана остаётся на своём месте
    scale() {
      return Math.max(100, this.percent === null ? 100 : this.percent)
    },

    fillWidth() {
      return this.percent === null ? 0 : (this.percent / this.scale) * 100 * this.progress
    },

    markLeft() {
      return (100 / this.scale) * 100
    },

    // «13,2 млн з 11,6 млн»: факт и план в миллионах
    compactText() {
      if (this.fact === null || this.plan === null) return ''
      const million = this.$t('kpi.million')
      return this.$t('kpi.ofPlan', {
        fact: `${this.number(this.fact / 1e6, 1)} ${million}`,
        plan: `${this.number(this.plan / 1e6, 1)} ${million}`,
      })
    },
  },

  watch: {
    // Данные пришли или изменились: анимация начинается с нуля
    loading(value) {
      if (!value) this.reveal()
    },

    signature() {
      if (!this.loading) this.reveal()
    },
  },

  mounted() {
    if (!this.loading) this.reveal()
  },

  beforeUnmount() {
    clearTimeout(this.startTimer)
    clearInterval(this.tween)
  },

  methods: {
    number(value, digits) {
      if (typeof value !== 'number') return '—'
      return new Intl.NumberFormat(this.locale, {
        minimumFractionDigits: digits,
        maximumFractionDigits: digits,
      }).format(value)
    },

    // Проигрывает появление; setInterval, а не requestAnimationFrame, чтобы работало и в фоновой вкладке
    reveal() {
      clearTimeout(this.startTimer)
      clearInterval(this.tween)
      this.progress = 0
      this.startTimer = setTimeout(() => {
        const started = Date.now()
        this.tween = setInterval(() => {
          const t = Math.min(1, (Date.now() - started) / ANIMATION_MS)
          this.progress = 1 - Math.pow(1 - t, 3)
          if (t === 1) clearInterval(this.tween)
        }, STEP_MS)
      }, 250 + this.index * 70)
    },
  },
}
</script>

