import { createI18n } from 'vue-i18n'
import { en as vuetifyEn, ru as vuetifyRu, uk as vuetifyUk } from 'vuetify/locale'
import { LOCALES } from '@/configurations'
import en from '@/locales/en.json'
import ru from '@/locales/ru.json'
import uk from '@/locales/uk.json'

export default createI18n({
  legacy: false,
  locale: LOCALES.DEFAULT,
  fallbackLocale: LOCALES.FALLBACK,
  messages: {
    ru: { ...ru, $vuetify: vuetifyRu },
    uk: { ...uk, $vuetify: vuetifyUk },
    en: { ...en, $vuetify: vuetifyEn },
  },
})
