// Цвет в формате #rrggbb или #rgb → строка «r, g, b» для rgba(var(--x), 0.5).
// Если цвет не разобрать, возвращается нейтральный серый.
export function hexToRgb(hex) {
  const match = /^#?([0-9a-f]{6}|[0-9a-f]{3})$/i.exec(String(hex).trim())
  if (!match) return '148, 163, 184'
  let value = match[1]
  if (value.length === 3) value = value.split('').map((char) => char + char).join('')
  const number = parseInt(value, 16)
  return `${(number >> 16) & 255}, ${(number >> 8) & 255}, ${number & 255}`
}

// Цвета состояния выполнения плана: это переменные темы, поэтому цвет сам меняется в светлой и тёмной теме
const STATE_RGB = {
  good: 'var(--v-theme-success)',
  warn: 'var(--v-theme-warning)',
  bad: 'var(--v-theme-error)',
  // Нет плана или данных: нейтральный серо-голубой, а не чёрный
  none: '148, 163, 184',
}

// Цвет записи в блоках сравнения (значение для --mc: RGB через запятую или переменная темы).
// На главной у каждого менеджера свой цвет из конфигурации. На странице РМ сравниваются магазины: они красятся
// не цветом менеджера, а по показателю — состоянием выполнения плана (зелёный, оранжевый, красный), как карточки.
export function entryRgb(kind, manager, state) {
  return kind === 'stores' ? STATE_RGB[state] || STATE_RGB.none : hexToRgb(manager.color)
}
