import { API } from '@/configurations'

export class GasError extends Error {
  constructor(code) {
    super(code)
    this.name = 'GasError'
    this.code = code
  }
}

// GET к веб-приложению Google Apps Script. Ответ GAS приходит с CORS-заголовком, поэтому браузер может его прочитать.
export async function gasGet(url, params = {}) {
  const query = new URLSearchParams(params).toString()
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), API.TIMEOUT)

  let response
  try {
    response = await fetch(query ? `${url}?${query}` : url, { signal: controller.signal })
  } catch {
    // Браузер не отличает обрыв сети от CORS-ошибки или таймаута, поэтому смотрим, есть ли сеть вообще
    throw new GasError(navigator.onLine === false ? 'network' : 'server_unreachable')
  } finally {
    clearTimeout(timer)
  }

  if (!response.ok) throw new GasError('server_error')

  try {
    return await response.json()
  } catch {
    throw new GasError('server_error')
  }
}
